  }

  // 最终安全锁：若预设末尾 setLastMessage:{{lastUserMessage}} 提供了权威最新发言，核对最后一轮 historyPairs 是否意外遗漏
  // 同时保护 shujuku 剧情推进（<本轮用户输入> / <plot>）：若历史消息已包裹完整剧情推进块且包含原始短句，绝不重复拼接或反向覆盖！
  if (historyPairs.length > 0 && explicitLastMessage) {
    const tailPair = historyPairs.at(-1);
    const normTail = stripForCompare(tailPair.userText);
    const normExplicit = stripForCompare(explicitLastMessage);
    if (normExplicit && !normTail.includes(normExplicit)) {
      if (normTail && normExplicit.includes(normTail)) {
        tailPair.userText = explicitLastMessage;
