    // 若消息流中的最新用户发言包含 shujuku <plot>/<本轮用户输入> 等增强包装且已覆盖 explicitLastMessage，优先保留完整增强版
    if (normExp && normCand.includes(normExp) && candidateHistoryTail.length >= explicitLastMessage.length) {
      lastLine = candidateHistoryTail;
    } else {
      lastLine = explicitLastMessage;
    }
  } else {
