  const initialMediaToAttach =
    activePairs.length === 0 && latestActualUserMedia.length > 0
      ? latestActualUserMedia
      : turn0FirstUserMedia;
  if (initialMediaToAttach.length > 0) {
    builtMessages.push({
      role: 'user',
