toolCallFormatter.script:
({ calls, defaultText }) => {
  if (!Array.isArray(calls) || calls.length === 0) {
    return defaultText ?? '';
  }

  const unescapeJsonStr = str =>
    str
      .replace(/\\n/g, '\n')
      .replace(/\\r/g, '\r')
      .replace(/\\t/g, '\t')
      .replace(/\\"/g, '"')
      .replace(/\\\\/g, '\\');

  // 流式半截 JSON 字符串兜底提取器
  const parsePartialArgs = raw => {
    const res = {};
    const keyRegex = /"([a-zA-Z0-9_]+)"\s*:\s*"((?:\\.|[^"\\])*)/g;
    let m;
    while ((m = keyRegex.exec(raw)) !== null) {
      res[m[1]] = unescapeJsonStr(m[2]);
    }
    return res;
  };

  // 仅在此表中的字段才自动补齐对应标签；extra / story_body 及其他额外字段一律原样输出不包标签
  const tagMap = {
    think_nya: 'think_nya',
    game_content: 'game',
    game: 'game',
    options: 'options',
    summary: 'summary',
    comment: 'comment',
  };

  const wrapTag = (val, tag) => {
    const trimmed = String(val ?? '').trim();
    if (!trimmed || !tag) return trimmed;

    // 1. 若内容中已经带有目标标签 <tag>，直接原样返回，绝不重复包裹
    const hasTargetTag = new RegExp(`<${tag}[\\s>]`, 'i').test(trimmed);
    const hasTargetTagClose = new RegExp(`<\/${tag}[\\s>]`, 'i').test(trimmed);
    if (hasTargetTag && hasTargetTagClose) return trimmed;

    // 2. 若 comment 字段里模型用了 <details> 折叠块，也直接原样返回
    if (tag === 'comment' && /^<details[\s>]/i.test(trimmed)) {
      return trimmed;
    }

    // 3. 若用户在【<game>标签（可改）】里改成了别的自定义标签（如 <novel>...</novel>），检测首尾成对标签直接放行
    if (
      tag === 'game' &&
      /^<([a-zA-Z0-9_-]+)>[\s\S]*<\/\1>$/.test(trimmed)
    ) {
      return trimmed;
    }

    return `<${tag}>\n${trimmed}\n</${tag}>`;
  };

  return calls
    .map(call => {
      let args = call?.arguments;
      if (typeof args === 'string') {
        try {
          args = JSON.parse(args);
        } catch {
          args = parsePartialArgs(args);
        }
      }

      if (!args || typeof args !== 'object') {
        return typeof call?.arguments === 'string' ? call.arguments : '';
      }

      if (
        typeof args.content === 'string' &&
        Object.keys(args).length === 1
      ) {
        return args.content;
      }

      const priorityOrder = [
        'think_nya',
        'game_content',
        'game',
        'story_body',
        'extra',
        'options',
        'summary',
        'comment',
      ];
      const extraKeys = Object.keys(args).filter(
        k => !priorityOrder.includes(k) && k !== 'nya_oath'
      );
      const finalKeyOrder = [...priorityOrder, ...extraKeys];

      const parts = [];

      for (const key of finalKeyOrder) {
        if (!(key in args)) continue;
        let val = String(args[key] ?? '').trim();
        if (!val) continue;

        if (key === 'think_nya') {
          val = val
            .replace(/`{3,}/g, '')
            .replace(/</g, '&lt;')
            .replace(/>/g, '&gt;');
        }

        const tag = tagMap[key] ?? null;
        let wrapped = wrapTag(val, tag);
        if (key === 'think_nya' && wrapped && !wrapped.includes('<!--</think>-->')) {
          wrapped += '<!--</think>-->';
        }
        parts.push(wrapped);
      }

      return parts.filter(Boolean).join('\n');
    })
    .filter(Boolean)
    .join('\n\n');
};

FinalRequestProcessing.script:
async ({ request }) => {
  const marker = '<run_tool_replacement>';
  const messages = request.messages;
  if (!Array.isArray(messages)) return request;

  const extractTextOnly = content =>
    Array.isArray(content)
      ? content
          .map(part => (typeof part === 'string' ? part : part?.text ?? ''))
          .join('\n')
      : String(content ?? '');

  const extractMediaParts = content =>
    Array.isArray(content)
      ? content.filter(
          part =>
            part &&
            typeof part === 'object' &&
            part.type &&
            part.type !== 'text'
        )
      : [];

  const hasMarker = messages.some(msg =>
    extractTextOnly(msg?.content).includes(marker)
  );
  if (!hasMarker) {
    return request;
  }

  // ── 0. 获取宿主窗口、SillyTavern 上下文与神域控制台状态 ──────────────────
  const resolveHostWin = () => {
    try {
      let cur = window;
      for (let i = 0; i < 8; i++) {
        if (cur?.SillyTavern) return cur;
        if (!cur.parent || cur === cur.parent) break;
        cur = cur.parent;
      }
      return window.top || window;
    } catch {
      return window;
    }
  };

  const hostWin = resolveHostWin();
  const ctx = (() => {
    try {
      return hostWin?.SillyTavern?.getContext?.() || null;
    } catch {
      return null;
    }
  })();

  let oracleState = {
    mode: 'theater',
    deepThink: false,
    rebuildCache: false,
    note: { text: '' },
  };
  try {
    const rawLocal = JSON.parse(
      hostWin?.localStorage?.getItem('CatGod_Oracle_State') || 'null'
    );
    const rawMeta = ctx?.chatMetadata?.catgod_oracle?.oracleState || null;
    const activeRaw =
      hostWin?.CatGodOracle?.state ||
      (rawLocal &&
      (!rawMeta ||
        Number(rawLocal.updatedAt || 0) >= Number(rawMeta.updatedAt || 0))
        ? rawLocal
        : rawMeta);
    if (activeRaw && typeof activeRaw === 'object') {
      oracleState = {
        mode: activeRaw.mode === 'chat' ? 'chat' : 'theater',
        deepThink: Boolean(activeRaw.deepThink),
        rebuildCache: Boolean(
          activeRaw.rebuildCache || hostWin?.__catgodPendingCacheRebuild
        ),
        note: {
          text:
            typeof activeRaw.note?.text === 'string'
              ? activeRaw.note.text.trim()
              : '',
        },
      };
    } else if (hostWin?.__catgodPendingCacheRebuild) {
      oracleState.rebuildCache = true;
    }
  } catch (e) {
    console.warn('[CatGod Stage1] Failed to read CatGod_Oracle_State:', e);
  }

  const isChatMode = oracleState.mode === 'chat';
  let enableDeepThink = oracleState.deepThink;
  let forceAutoTool = /^pg-/i.test(String(request.model ?? ''));
  let explicitLastMessage = null;
  const registeredParts = [];
  const registeredThinkingStepItems = [];
  let thinkingStepSeq = 0;

  function parseAndRegisterThinkingStep(rawBody) {
    let body = String(rawBody ?? '').trim();
    if (!body) return;

    let order = 100;
    const orderMatch = body.match(/^(-?\d+(?:\.\d+)?)\s*[:：]\s*([\s\S]*)$/);
    if (orderMatch) {
      order = Number(orderMatch[1]);
      body = orderMatch[2].trim();
    }
    if (!body) return;

    const titleMatch = body.match(/^([^:：\r\n]{1,20})\s*[:：]\s*([\s\S]+)$/);
    const stepText = titleMatch
      ? `【${titleMatch[1].trim()}】${titleMatch[2].trim()}`
      : body;

    if (!stepText) return;
    const existing = registeredThinkingStepItems.find(x => x.text === stepText);
    if (existing) {
      if (orderMatch) existing.order = order;
      return;
    }
    registeredThinkingStepItems.push({
      order: Number.isFinite(order) ? order : 100,
      seq: thinkingStepSeq++,
      text: stepText,
    });
  }

  // ── 0.5 第三方插件深度兼容底座（TavernHelper MVU 变量宏 + ST-Prompt-Template EJS + 柏宝书 + 龙血玄黄·数据库 shujuku） ──
  const liveChat = Array.isArray(ctx?.chat) ? ctx.chat : null;
  let lastUserChatIdx = -1;
  let prevUserChatIdx = -1;
  const liveVisibleMsgs = [];
  if (liveChat && liveChat.length > 0) {
    for (let i = 0; i < liveChat.length; i++) {
      const m = liveChat[i];
      if (!m || m.is_system) continue;
      liveVisibleMsgs.push({ m, index: i });
      if (m.is_user) {
        prevUserChatIdx = lastUserChatIdx;
        lastUserChatIdx = i;
      }
    }
  }

  // 判断当前请求是否正在 Swipe / 重生成末尾 AI 消息（用于对齐 EJS prepareContext 游标与 MVU 楼层变量回溯）
  const lastVisEntry =
    liveVisibleMsgs.length > 0 ? liveVisibleMsgs[liveVisibleMsgs.length - 1] : null;
  const isSwipingAiTail = Boolean(lastVisEntry && !lastVisEntry.m.is_user);

  function omitDollarKeysDeep(val) {
    if (Array.isArray(val)) {
      return val.map(omitDollarKeysDeep);
    }
    if (val && typeof val === 'object') {
      const out = {};
      for (const [k, v] of Object.entries(val)) {
        if (k.startsWith('$')) continue;
        out[k] = omitDollarKeysDeep(v);
      }
      return out;
    }
    return val;
  }

  function hasNonEmptyVarPayload(obj) {
    if (!obj || typeof obj !== 'object') return false;
    for (const [k, v] of Object.entries(obj)) {
      if (k.startsWith('$')) continue;
      if (v !== undefined) return true;
    }
    return false;
  }

  function unescapeHtmlBasic(str) {
    return String(str ?? '')
      .replace(/&quot;/g, '"')
      .replace(/&#39;/g, "'")
      .replace(/&lt;/g, '<')
      .replace(/&gt;/g, '>')
      .replace(/&amp;/g, '&');
  }

  function getNestedByPath(rootObj, rawPath) {
    if (!rootObj || typeof rootObj !== 'object') return null;
    const cleaned = omitDollarKeysDeep(rootObj);
    const p = unescapeHtmlBasic(rawPath).trim();
    if (!p || p === '.') return cleaned;
    const tokens = [];
    const tokenRe = /[^.[\]]+|\[(?:(\d+)|"([^"]*)"|'([^']*)')\]/g;
    let m;
    while ((m = tokenRe.exec(p)) !== null) {
      tokens.push(m[1] ?? m[2] ?? m[3] ?? m[0]);
    }
    let cur = cleaned;
    for (const tk of tokens) {
      if (cur === null || cur === undefined || typeof cur !== 'object') return null;
      cur = cur[tk];
    }
    return cur === undefined ? null : cur;
  }

  function stringifyYamlFallback(value, quoteStrings = false, indent = 0) {
    const pad = ' '.repeat(indent);
    if (value === null || value === undefined) return 'null';
    if (typeof value === 'boolean' || typeof value === 'number') return String(value);
    if (typeof value === 'string') {
      if (value.includes('\n')) {
        const lines = value.replace(/\n$/, '').split('\n');
        return '|\n' + lines.map(l => `${' '.repeat(indent + 2)}${l}`).join('\n');
      }
      if (quoteStrings) return JSON.stringify(value);
      if (
        value === '' ||
        /^(?:true|false|null|~|-?\d+(?:\.\d+)?)$/i.test(value) ||
        /^[\s?:,\-[\]{}#&*!|>'"%@`]|:\s|#\s|\s$/.test(value)
      ) {
        return JSON.stringify(value);
      }
      return value;
    }
    if (Array.isArray(value)) {
      if (value.length === 0) return '[]';
      return value
        .map(item => {
          if (item && typeof item === 'object') {
            const sub = stringifyYamlFallback(item, quoteStrings, indent + 2);
            if (Array.isArray(item) && item.length === 0) return `${pad}- []`;
            if (!Array.isArray(item) && Object.keys(item).length === 0) return `${pad}- {}`;
            const subTrimmed = sub.startsWith(' '.repeat(indent + 2))
              ? sub.slice(indent + 2)
              : sub;
            return `${pad}- ${subTrimmed}`;
          }
          const rendered = stringifyYamlFallback(item, quoteStrings, indent + 2);
          return rendered.startsWith('|')
            ? `${pad}- ${rendered}`
            : `${pad}- ${rendered}`;
        })
        .join('\n');
    }
    if (typeof value === 'object') {
      const keys = Object.keys(value);
      if (keys.length === 0) return '{}';
      return keys
        .map(k => {
          const safeKey = /^[\w\u4e00-\u9fa5-]+$/.test(k) ? k : JSON.stringify(k);
          const v = value[k];
          if (v && typeof v === 'object') {
            if (Array.isArray(v) && v.length === 0) return `${pad}${safeKey}: []`;
            if (!Array.isArray(v) && Object.keys(v).length === 0) return `${pad}${safeKey}: {}`;
            return `${pad}${safeKey}:\n${stringifyYamlFallback(v, quoteStrings, indent + 2)}`;
          }
          const rendered = stringifyYamlFallback(v, quoteStrings, indent);
          return `${pad}${safeKey}: ${rendered}`;
        })
        .join('\n');
    }
    return String(value);
  }

  function formatMvuYamlValue(value, quoteStrings = false) {
    if (typeof value === 'string') return value;
    try {
      if (hostWin?.YAML && typeof hostWin.YAML.stringify === 'function') {
        const opts = quoteStrings
          ? {
              blockQuote: 'literal',
              defaultKeyType: 'PLAIN',
              defaultStringType: 'QUOTE_DOUBLE',
            }
          : { blockQuote: 'literal' };
        return String(hostWin.YAML.stringify(value, opts)).trimEnd();
      }
    } catch {
      /* fallback to built-in YAML serializer */
    }
    return stringifyYamlFallback(value, quoteStrings, 0).trimEnd();
  }

  function readTavernHelperVariables(rawType, messageIdHint = undefined) {
    const type = String(rawType ?? 'message').toLowerCase();
    const th = hostWin?.TavernHelper;
    if (type === 'message') {
      const total = Array.isArray(liveChat) ? liveChat.length : 0;
      let startIdx =
        typeof messageIdHint === 'number' && messageIdHint >= 0
          ? Math.min(messageIdHint, total - 1)
          : isSwipingAiTail
            ? total - 2
            : total - 1;
      for (let idx = startIdx; idx >= 0; idx--) {
        let candidate = null;
        try {
          if (th && typeof th.getVariables === 'function') {
            candidate = th.getVariables({ type: 'message', message_id: idx });
          }
        } catch {
          candidate = null;
        }
        if (!hasNonEmptyVarPayload(candidate) && liveChat?.[idx]) {
          const msg = liveChat[idx];
          const swipeIdx = msg.swipe_id ?? 0;
          const nativeVar = msg.variables?.[swipeIdx];
          if (hasNonEmptyVarPayload(nativeVar)) candidate = nativeVar;
        }
        if (hasNonEmptyVarPayload(candidate)) return candidate;
      }
      // 若所有楼层都没有非空快照，尝试读最新一层或 chat 层兜底
      try {
        if (th && typeof th.getVariables === 'function') {
          return th.getVariables({ type: 'message' }) || {};
        }
      } catch {
        /* ignore */
      }
      return {};
    }
    try {
      if (th && typeof th.getVariables === 'function') {
        const res = th.getVariables({ type });
        if (res && typeof res === 'object') return res;
      }
    } catch {
      /* ignore */
    }
    if (type === 'chat') return ctx?.chatMetadata?.variables || {};
    if (type === 'global') return ctx?.extensionSettings?.variables?.global || {};
    return {};
  }

  const TH_GET_VAR_RE =
    /\{\{get_(message|chat|character|preset|global)_variable::(.*?)\}\}/gi;
  const TH_FMT_QUOTED_LINE_RE =
    /^(.*)\{\{format_(message|chat|character|preset|global)_variable_quoted::(.*?)\}\}/gim;
  const TH_FMT_QUOTED_SINGLE_RE =
    /^(.*)\{\{format_(message|chat|character|preset|global)_variable_quoted::(.*?)\}\}/im;
  const TH_FMT_PLAIN_LINE_RE =
    /^(.*)\{\{format_(message|chat|character|preset|global)_variable::(.*?)\}\}/gim;
  const TH_FMT_PLAIN_SINGLE_RE =
    /^(.*)\{\{format_(message|chat|character|preset|global)_variable::(.*?)\}\}/im;

  function expandTavernHelperVarMacros(inputText, messageIdHint = undefined) {
    let text = String(inputText ?? '');
    if (
      !text ||
      !/\{\{(?:get|format)_(?:message|chat|character|preset|global)_variable/i.test(
        text
      )
    ) {
      return text;
    }

    text = text.replace(TH_GET_VAR_RE, (_sub, type, path) => {
      const vars = readTavernHelperVariables(type, messageIdHint);
      const val = getNestedByPath(vars, path);
      return typeof val === 'string' ? val : JSON.stringify(val);
    });

    const applyFmtQuoted = (_sub, prefix, type, path) => {
      let resolvedPrefix = prefix;
      const m = resolvedPrefix.match(TH_FMT_QUOTED_SINGLE_RE);
      if (m) {
        resolvedPrefix =
          applyFmtQuoted('', m[1], m[2], m[3]) +
          resolvedPrefix.slice(m[0].length);
      }
      const vars = readTavernHelperVariables(type, messageIdHint);
      const val = getNestedByPath(vars, path);
      const formatted = formatMvuYamlValue(val, true);
      return (
        resolvedPrefix +
        formatted.replaceAll('\n', '\n' + ' '.repeat(resolvedPrefix.length))
      );
    };

    const applyFmtPlain = (_sub, prefix, type, path) => {
      let resolvedPrefix = prefix;
      const m = resolvedPrefix.match(TH_FMT_PLAIN_SINGLE_RE);
      if (m) {
        resolvedPrefix =
          applyFmtPlain('', m[1], m[2], m[3]) +
          resolvedPrefix.slice(m[0].length);
      }
      const vars = readTavernHelperVariables(type, messageIdHint);
      const val = getNestedByPath(vars, path);
      const formatted = formatMvuYamlValue(val, false);
      return (
        resolvedPrefix +
        formatted.replaceAll('\n', '\n' + ' '.repeat(resolvedPrefix.length))
      );
    };

    text = text.replace(TH_FMT_QUOTED_LINE_RE, applyFmtQuoted);
    text = text.replace(TH_FMT_PLAIN_LINE_RE, applyFmtPlain);
    return text;
  }

  // 检测是否包含任何动态模板语法（EJS / TavernHelper 变量宏 / ST 动态变量宏 / shujuku 动态标签）
  function hasDynamicTemplateSyntax(raw) {
    const s = String(raw ?? '');
    if (!s) return false;
    return (
      /<%[\s\S]*?%>/.test(s) ||
      /\{\{(?:get|format)_(?:message|chat|character|preset|global)_variable(?:_quoted)?::/i.test(
        s
      ) ||
      /\{\{(?:getvar|getglobalvar|setvar|addvar|incvar|decvar|random|roll|pick)::/i.test(
        s
      ) ||
      /<(?:random|calc|max|min)\b[^>]*\/?>|<if\s+(?:seed|cell|cond|db|sql)=|\{\[(?:db\.|sql\s)/i.test(
        s
      )
    );
  }

  function hasShujukuDynamicTemplateSyntax(raw) {
    return /<(?:random|calc|max|min)\b[^>]*\/?>|<if\s+(?:seed|cell|cond|db|sql)=|\{\[(?:db\.|sql\s)/i.test(
      String(raw ?? '')
    );
  }

  function hasEjsWriteSideEffect(raw) {
    return /<%[\s\S]*?\b(?:setvar|addvar|incvar|decvar|setChatVar|setGlobalVar|setLocalVariable|setGlobalVariable|insertOrAssignVariables|assignVariables|updateVariablesWith|replaceVariables|deleteVariable)\b[\s\S]*?%>/i.test(
      String(raw ?? '')
    );
  }

  let cachedEjsEnv = undefined;
  async function getSharedEjsEnv() {
    if (cachedEjsEnv !== undefined) return cachedEjsEnv;
    const ejsApi = hostWin?.EjsTemplate;
    if (!ejsApi || typeof ejsApi.prepareContext !== 'function') {
      cachedEjsEnv = null;
      return null;
    }
    try {
      const endIdx = isSwipingAiTail ? -2 : -1;
      const rawEnv = await ejsApi.prepareContext({}, endIdx);
      if (rawEnv && typeof rawEnv === 'object') {
        // ST-Prompt-Template 已在 CHAT_COMPLETION_SETTINGS_READY 执行过一次真实写变量；
        // 此处包装写函数为无持久化副作用的只读保护层，防止 setvar/incvar/insertOrAssignVariables 在同轮被重复累加两次！
        const safeEnv = Object.create(rawEnv);
        const noopAsync = async v => v;
        const noopSync = v => v;
        for (const fnName of [
          'setvar',
          'addvar',
          'incvar',
          'decvar',
          'setChatVar',
          'setGlobalVar',
          'setLocalVariable',
          'setGlobalVariable',
        ]) {
          if (typeof rawEnv[fnName] === 'function') safeEnv[fnName] = noopSync;
        }
        for (const asyncFnName of [
          'insertOrAssignVariables',
          'assignVariables',
          'updateVariablesWith',
          'replaceVariables',
          'deleteVariable',
        ]) {
          if (typeof rawEnv[asyncFnName] === 'function') {
            safeEnv[asyncFnName] = noopAsync;
          }
        }
        cachedEjsEnv = safeEnv;
      } else {
        cachedEjsEnv = rawEnv;
      }
    } catch (e) {
      console.warn('[CatGod Stage1] EjsTemplate.prepareContext failed:', e);
      cachedEjsEnv = null;
    }
    return cachedEjsEnv;
  }

  async function compileDynamicEntryText(rawContent) {
    let text = String(rawContent ?? '');
    if (!text) return '';
    // 1) 先展开酒馆原生基础宏（若条目尚未经 substituteParams 替换）与 TavernHelper MVU 变量宏
    if (text.includes('{{') && typeof ctx?.substituteParams === 'function') {
      try {
        // 保护 TavernHelper 私有宏不被误破坏，先展开 TavernHelper 再跑原生 substituteParams
        text = expandTavernHelperVarMacros(text);
        if (/\{\{(?!(?:get|format)_(?:message|chat|character|preset|global)_variable)/i.test(text)) {
          text = ctx.substituteParams(text);
        }
      } catch {
        text = expandTavernHelperVarMacros(text);
      }
    } else {
      text = expandTavernHelperVarMacros(text);
    }

    // 2) 若含 ST-Prompt-Template 的 EJS <% %> / <%_ %> 标签，实时异步编译
    if (/<%[\s\S]*?%>/.test(text) && typeof hostWin?.EjsTemplate?.evalTemplate === 'function') {
      try {
        const env = await getSharedEjsEnv();
        const evaluated = await hostWin.EjsTemplate.evalTemplate(text, env);
        text = typeof evaluated === 'string' ? evaluated : String(evaluated ?? '');
        // EJS 输出里若动态拼出了 MVU 变量宏，二次展开一次
        if (text.includes('{{')) {
          text = expandTavernHelperVarMacros(text);
        }
      } catch (e) {
        console.warn('[CatGod Stage1] EjsTemplate.evalTemplate failed:', e);
      }
    }
    return text.trim();
  }

  // 柏宝书（ST-BaiBai-Book）与龙血玄黄·数据库（shujuku）特征识别函数
  function isBaiBaiHistoryChunk(s) {
    const t = String(s ?? '');
    return t.includes('[历史剧情摘要]');
  }
  function isBaiBaiBriefingChunk(s) {
    const t = String(s ?? '');
    return (
      !t.includes('[历史剧情摘要]') &&
      (t.includes('〔记忆系统私密简报') ||
        t.includes('[当前状态]') ||
        t.includes('[相关回忆]') ||
        t.includes('[相关过往记忆]'))
    );
  }
  function isBaiBaiTimeTagChunk(s) {
    const t = String(s ?? '');
    return (
      t.includes('<bbs_start>') &&
      (t.includes('【时间锚点要求') || t.includes('【柏宝书旁注读取与正文分工】'))
    );
  }
  function normalizeAcuComment(rawComment) {
    return String(rawComment ?? '')
      .trim()
      .replace(/^外部导入-/, '')
      .replace(/^ACU-\[[^\]]*\]-/, '');
  }
  const knownAcuCustomEntryNames = (() => {
    const set = new Set();
    try {
      const ext = ctx?.extensionSettings || {};
      for (const val of Object.values(ext)) {
        if (val && typeof val === 'object' && Array.isArray(val.knownCustomEntryNames)) {
          for (const n of val.knownCustomEntryNames) {
            if (typeof n === 'string' && n.trim()) set.add(normalizeAcuComment(n));
          }
        }
      }
    } catch {
      /* ignore */
    }
    return set;
  })();

  function isShujukuEntryComment(rawComment) {
    const nc = normalizeAcuComment(rawComment);
    if (!nc) return false;
    return (
      nc.startsWith('TavernDB-ACU-') ||
      /^(?:总结条目|小总结条目|重要人物条目)\d*$/.test(nc) ||
      knownAcuCustomEntryNames.has(nc)
    );
  }

  function isShujukuArchiveComment(rawComment) {
    const nc = normalizeAcuComment(rawComment);
    return (
      nc.startsWith('TavernDB-ACU-OutlineTable') ||
      nc.startsWith('TavernDB-ACU-PersonsHeader') ||
      nc.startsWith('TavernDB-ACU-ImportantPersonsIndex') ||
      /^重要人物条目\d*$/.test(nc) ||
      /^TavernDB-ACU-CustomExport-(?:重要角色表|重要人物表|大总结)/.test(nc) ||
      nc === '大总结'
    );
  }

  function isShujukuFormattedChunk(s) {
    const t = String(s ?? '');
    return (
      /<\/?(?:最新数据与记录|剧情大纲编码索引|过往记忆|记忆回溯|已发生的事件概览|大总结|已登场角色|重要角色索引)>/.test(
        t
      ) || /^#\s*(?:全局数据表|纪要索引|总体大纲|重要人物表)\b/m.test(t)
    );
  }

  // 用于旧存档脏账本自动自愈：凡含未编译模板源码、未展开变量宏、柏宝书简报或 shujuku 表格的条目一律从静态账本剥除
  function isDirtyDynamicLedgerChunk(s) {
    const t = String(s ?? '').trim();
    if (!t) return true;
    return (
      hasDynamicTemplateSyntax(t) ||
      isBaiBaiHistoryChunk(t) ||
      isBaiBaiBriefingChunk(t) ||
      isBaiBaiTimeTagChunk(t) ||
      isShujukuFormattedChunk(t)
    );
  }

  // ── 1. 内置平替版 squashed_post_script（无需开启 ChatSquash 即可将文本块转为伪 JSON 对话流） ──
  let detectedUsername = '用户';
  function convertPipeRolesToJson(rawContent, isFirstChunk = false) {
    let text = String(rawContent ?? '');
    if (!text.trim()) return '';

    // 若文本已经是 squashed_post_script 转换过的 JSON 格式（兼容用户仍开着 ChatSquash 的情况），直接返回
    if (text.includes('"}, {"role": "soliumbra", "content": "')) {
      return text;
    }

    const usernameRegex = /\|用户：(.*?)\|/;
    const usernameMatches = text.match(usernameRegex);
    if (usernameMatches && usernameMatches.length > 1) {
      detectedUsername = usernameMatches[1].trim() || '用户';
    }
    text = text.replace(usernameRegex, '');

    const deleteRegex = /\|delete\|[\s\S]*?\|\/delete\|/g;
    text = text.replace(deleteRegex, '');

    const roleMap = {
      '小猫之神': 'soliumbra',
      '友人': '友人',
      '模型': 'model',
      'model': 'model',
    };

    const parts = text.split(/[\n]*\|(小猫之神|用户|友人|模型|model)\|/g);
    if (parts.length <= 1) {
      // 没有角色分隔符的普通设定块，仅做 JSON 字符串内部转义
      const escaped = JSON.stringify(text).slice(1, -1);
      return escaped;
    }

    const segs = [];
    const leading = parts[0].trim();
    if (leading) {
      segs.push(JSON.stringify(leading).slice(1, -1));
    }

    for (let i = 1; i < parts.length; i += 2) {
      const rawRole = parts[i];
      const role =
        rawRole === '用户' ? detectedUsername : roleMap[rawRole] || rawRole;
      const body = parts[i + 1] ?? '';
      const escapedBody = JSON.stringify(body).slice(1, -1);
      if (i === 1 && isFirstChunk && !leading) {
        segs.push(escapedBody);
      } else {
        segs.push(`\\n"}, {"role": "${role}", "content": "\\n${escapedBody}`);
      }
    }
    return segs.join('');
  }

  // ── 2. 外人预设正文清洗与猫神血统识别函数 ────────────────────────────────
  function extractCleanStoryFromForeignReply(rawText) {
    let text = String(rawText ?? '').trim();
    if (!text) return '';

    // 保护柏宝书（ST-BaiBai-Book）首尾时间标签/结算旁注与 shujuku 格林推演隐藏尾注不被外人清洗器剥除
    const bbsStartTags = [
      ...text.matchAll(/<bbs_start>[\s\S]*?<\/bbs_start>/gi),
    ].map(m => m[0]);
    const bbsTailTags = [
      ...text.matchAll(/<bbs_(?:end|items|vars)>[\s\S]*?<\/bbs_(?:end|items|vars)>/gi),
    ].map(m => m[0]);
    const qrfSimTags = [
      ...text.matchAll(
        /<!--\s*qrf-world-simulation-projection:v\d+:start\s*-->[\s\S]*?<!--\s*qrf-world-simulation-projection:v\d+:end\s*-->/gi
      ),
    ].map(m => m[0]);

    text = text
      .replace(/<bbs_(?:start|end|items|vars)>[\s\S]*?<\/bbs_(?:start|end|items|vars)>/gi, '')
      .replace(
        /<!--\s*qrf-world-simulation-projection:v\d+:start\s*-->[\s\S]*?<!--\s*qrf-world-simulation-projection:v\d+:end\s*-->/gi,
        ''
      )
      .replace(
        /<details\b[^>]*>\s*<summary\b[^>]*>[^<]*(?:思考|思维|推演|分析|状态|面板|think|thought|cot|reasoning|status|info)[^<]*<\/summary>[\s\S]*?<\/details>/gi,
        ''
      )
      .replace(
        /<(think|thinking|thought|thoughts|cot|reasoning|reflection|analysis|status|state|status_bar|options|choices|summary|comment|memory|variables|script|style)\b[^>]*>[\s\S]*?<\/\1>/gi,
        ''
      )
      .replace(
        /```(?:json|yaml|yml|xml|html|css|js|javascript|status|state|data)\b[\s\S]*?```/gi,
        ''
      )
      .trim();

    const candidates = [];
    const tagBlockRegex = /<([a-zA-Z0-9_-]+)\b[^>]*>([\s\S]*?)<\/\1>/g;
    let outsideText = text;
    let match;
    while ((match = tagBlockRegex.exec(text)) !== null) {
      const inner = match[2].replace(/<\/?[a-zA-Z][^>]*>/g, '').trim();
      if (inner) candidates.push(inner);
    }

    outsideText = outsideText
      .replace(tagBlockRegex, '\n')
      .replace(/<\/?[a-zA-Z][^>]*>/g, '')
      .trim();
    if (outsideText) candidates.push(outsideText);

    const coreBody = candidates.length
      ? candidates.sort((a, b) => b.length - a.length)[0]
      : text;
    return [...bbsStartTags, coreBody, ...bbsTailTags, ...qrfSimTags]
      .filter(Boolean)
      .join('\n');
  }

  function normalizeAssistantReply(
    rawMes,
    isFirstGreeting = false,
    forceCatGodHint = false
  ) {
    const raw = String(rawMes ?? '').trim();
    if (!raw) {
      return {
        isCatGod: Boolean(forceCatGodHint),
        game_content: '<game>\n（序幕拉开）\n</game>',
        summary: '',
      };
    }

    const thinkMatch = raw.match(
      /<(?:think_nya|report_nya)~?>([\s\S]*?)<\/(?:think_nya|report_nya)~?>/i
    );
    const hasCatGodTags =
      /<(?:game|options|comment)\b[^>]*>[\s\S]*?<\/(?:game|options|comment)>/i.test(
        raw
      ) ||
      /<details\b[^>]*>\s*<summary\b[^>]*>[^<]*小猫之神[^<]*<\/summary>/i.test(
        raw
      );
    const summaryMatches = [
      ...raw.matchAll(
        /(?<!<details\b[^>]*>\s*)<summary\b[^>]*>([\s\S]*?)<\/summary>/gi
      ),
      ...raw.matchAll(
        /<details\b[^>]*>\s*<summary\b[^>]*>\s*(?:摘要|剧情小总结|总结)\s*<\/summary>([\s\S]*?)<\/details>/gi
      ),
    ];
    const extractedSummary = summaryMatches
      .map(m => m[1].trim())
      .filter(Boolean)
      .join('\n');

    if (forceCatGodHint || thinkMatch || hasCatGodTags) {
      // 未归档的活跃轮次：剥除 <think_nya>、<summary>、<options>，保留正文（兼容关闭 <game> 标签或自定义标签及本体聊天模式）与 <comment> 猫猫留言！
      let bodyText = raw
        .replace(
          /<details\b[^>]*>\s*<summary\b[^>]*>[^<]*(?:小猫之神的思考|摘要|剧情小总结)[^<]*<\/summary>[\s\S]*?<\/details>/gi,
          ''
        )
        .replace(
          /<(?:think_nya|report_nya)~?>[\s\S]*?<\/(?:think_nya|report_nya)~?>(?:<!--<\/think>-->)?/gi,
          ''
        )
        .replace(
          /(?<!<details\b[^>]*>\s*)<summary\b[^>]*>[\s\S]*?<\/summary>/gi,
          ''
        )
        .replace(/<options\b[^>]*>[\s\S]*?<\/options>/gi, '')
        .trim();

      if (!bodyText) {
        bodyText = '<game>\n（剧情继续推进）\n</game>';
      }
      return {
        isCatGod: true,
        game_content: bodyText,
        summary: extractedSummary,
      };
    }

    const cleanStory = isFirstGreeting
      ? raw
      : extractCleanStoryFromForeignReply(raw);
    const autoSummary =
      extractedSummary || cleanStory.slice(0, 180).replace(/\s+/g, ' ');
    return {
      isCatGod: false,
      game_content: `<game>\n${cleanStory || raw}\n</game>`,
      summary: autoSummary,
    };
  }

  function formatInitialArchiveMessage(rawMes, isHiddenOffset = false) {
    const raw = String(rawMes ?? '').trim();
    if (!raw) return '';
    const sumMatches = [
      ...raw.matchAll(
        /(?<!<details\b[^>]*>\s*)<summary\b[^>]*>([\s\S]*?)<\/summary>/gi
      ),
      ...raw.matchAll(
        /<details\b[^>]*>\s*<summary\b[^>]*>\s*(?:摘要|剧情小总结|总结)\s*<\/summary>([\s\S]*?)<\/details>/gi
      ),
    ];
    const sumText = sumMatches
      .map(m => m[1].trim())
      .filter(Boolean)
      .join('\n');
    const gameMatch = raw.match(/<game\b[^>]*>([\s\S]*?)<\/game>/i);
    if (sumText && (!gameMatch || isHiddenOffset)) {
      const gameBody = gameMatch ? `\n${gameMatch[1].trim()}` : '';
      return `---前情大总结与序幕基准---\n${sumText}${gameBody}\n---`;
    }
    const cleanGreeting = gameMatch
      ? gameMatch[1].trim()
      : extractCleanStoryFromForeignReply(raw) || raw;
    return `---序幕开场剧情---\n${cleanGreeting}${sumText ? `\n【场记摘要】：\n${sumText}` : ''}\n---`;
  }

  // ── 3. 直接扫描原生 request.messages（同时兼容未开启 ChatSquash 的多条消息与开启 ChatSquash 的合并消息） ──
  const extractedWiChunks = [];
  const inlineDepthWiList = []; // { text, isD0 }
  const nativeChatMsgs = [];    // { role: 'user' | 'model', text, mediaParts }
  const preHistChunks = [];
  const postHistChunks = [];

  const catgodmlRegex = /<<<\|\s*catgodml\s*\|([\s\S]*?)>>>/gi;

  // 剥除末尾独立的 <think> 预填充消息
  let cleanMessages = [...messages];
  while (cleanMessages.length > 1) {
    const lastMsg = cleanMessages.at(-1);
    const lastText = extractTextOnly(lastMsg?.content).trim();
    const isStandalonePrefill =
      (lastText.startsWith('<think>') && lastText.length < 600) ||
      lastText === '';
    if (isStandalonePrefill && extractMediaParts(lastMsg?.content).length === 0) {
      cleanMessages.pop();
    } else {
      break;
    }
  }

  // 状态机阶段：'before_hist' -> 'in_hist' -> 'after_hist'
  // 同时跟踪 wiStart:before / wiStart:after
  let phase = 'before_hist';
  let inOuterWi = false;
  let outerWiBuffer = [];
  const renderedMessagesPieces = [];

  for (let mIdx = 0; mIdx < cleanMessages.length; mIdx++) {
    const msg = cleanMessages[mIdx];
    const role = msg?.role || 'system';
    const mediaParts = extractMediaParts(msg?.content);
    let text = expandTavernHelperVarMacros(
      extractTextOnly(msg?.content)
        .replaceAll(marker, '')
        .replace(/<\|sep\|>/g, '')
        .replace(/<\|merge\|>/g, '')
    );
    if (text) renderedMessagesPieces.push(text);

    // 先处理全局控制宏（deepthink / autotool / setLastMessage / registerPart / menu / radio）
    text = text.replace(catgodmlRegex, (fullMatch, rawDirective) => {
      const directive = rawDirective.trim();
      const lower = directive.toLowerCase();

      if (lower === 'deepthink') {
        enableDeepThink = true;
        return '';
      }
      if (lower === 'autotool') {
        forceAutoTool = true;
        return '';
      }
      if (lower.startsWith('setlastmessage:')) {
        const msgVal = directive.slice('setLastMessage:'.length).trim();
        if (msgVal) explicitLastMessage = msgVal;
        return '';
      }
      if (lower.startsWith('registerpart:')) {
        const rest = directive.slice('registerPart:'.length);
        const colonIdx = rest.indexOf(':');
        if (colonIdx !== -1) {
          const partName = rest.slice(0, colonIdx).trim();
          const partDesc = rest.slice(colonIdx + 1).trim();
          if (partName) {
            registeredParts.push({ name: partName, description: partDesc });
          }
        }
        return '';
      }
      if (lower.startsWith('registerthinkingstep:')) {
        parseAndRegisterThinkingStep(directive.slice('registerThinkingStep:'.length));
        return '';
      }
      if (lower.startsWith('menu:') || lower.startsWith('radio:')) {
        return '';
      }
      // 保留结构边界标记供下方状态机处理
      return fullMatch;
    });

    // 若是在未开启 ChatSquash 的原生多消息模式下：
    // 当处于 'in_hist' 阶段（即 historyStart 与 historyEnd 之间）时：
    // - role === 'user' 或 role === 'assistant' 直接就是原生聊天消息（且完美带有 mediaParts 图片数组！）
    // - role === 'system'（且不含 historyEnd）直接就是酒馆按 @D0~@D4 插进聊天记录的深度世界书！
    const hasHistStart = /<<<\|\s*catgodml\s*\|\s*historyStart\s*>>>/i.test(text);
    const hasHistEnd = /<<<\|\s*catgodml\s*\|\s*historyEnd\s*>>>/i.test(text);

    if (
      phase === 'in_hist' &&
      !hasHistStart &&
      !hasHistEnd &&
      !/<<<\|\s*catgodml\s*\|/i.test(text)
    ) {
      if (role === 'user' || role === 'assistant' || role === 'model') {
        const normRole = role === 'user' ? 'user' : 'model';
        if (text.trim() || mediaParts.length > 0) {
          nativeChatMsgs.push({
            role: normRole,
            text: text.trim(),
            mediaParts,
            afterMsgIndex: nativeChatMsgs.length,
          });
        }
        continue;
      } else if (role === 'system') {
        // 原生插在 chatHistory 内部的 @D0~@D4 深度世界书！
        const wText = text.trim();
        if (wText) {
          inlineDepthWiList.push({
            text: wText,
            msgCountBefore: nativeChatMsgs.length,
          });
        }
        continue;
      }
    }

    // 处理包含边界标记的消息（兼容原生多消息模式与开启了 ChatSquash 的合并模式）
    // 1) 检查 wiStart:before/after .. wiEnd:before/after
    const wiStartRe = /<<<\|\s*catgodml\s*\|\s*wiStart:(?:before|after)\s*>>>/i;
    const wiEndRe = /<<<\|\s*catgodml\s*\|\s*wiEnd:(?:before|after)\s*>>>/i;

    // 如果同一条消息内成对包含 wiStart..wiEnd
    text = text.replace(
      /<<<\|\s*catgodml\s*\|\s*wiStart:(?:before|after)\s*>>>([\s\S]*?)<<<\|\s*catgodml\s*\|\s*wiEnd:(?:before|after)\s*>>>/gi,
      (_, wiBody) => {
        const cleaned = String(wiBody ?? '').replace(/\\n/g, '\n').trim();
        if (cleaned) {
          extractedWiChunks.push(
            ...cleaned
              .split(/\n{2,}/)
              .map(b => b.trim())
              .filter(b => b.length > 2 && !/^["'},\s]+$/.test(b))
          );
        }
        return '';
      }
    );

    if (wiStartRe.test(text) && !wiEndRe.test(text)) {
      const [beforeWi, afterWi] = text.split(wiStartRe);
      if (beforeWi.trim()) {
        (phase === 'after_hist' ? postHistChunks : preHistChunks).push(beforeWi.trim());
      }
      inOuterWi = true;
      outerWiBuffer = afterWi?.trim() ? [afterWi.trim()] : [];
      continue;
    }

    if (inOuterWi) {
      if (wiEndRe.test(text)) {
        const [insideWi, afterWiEnd] = text.split(wiEndRe);
        if (insideWi?.trim()) outerWiBuffer.push(insideWi.trim());
        const combinedWi = outerWiBuffer.join('\n\n').trim();
        if (combinedWi) {
          extractedWiChunks.push(
            ...combinedWi
              .split(/\n{2,}/)
              .map(b => b.trim())
              .filter(b => b.length > 2 && !/^["'},\s]+$/.test(b))
          );
        }
        inOuterWi = false;
        outerWiBuffer = [];
        text = afterWiEnd ?? '';
      } else {
        if (text.trim()) outerWiBuffer.push(text.trim());
        continue;
      }
    }

    // 2) 检查 historyStart 与 historyEnd
    if (hasHistStart && hasHistEnd) {
      // 同一条消息里既有 historyStart 又有 historyEnd（说明用户开启了 ChatSquash）
      const sMatch = text.match(/<<<\|\s*catgodml\s*\|\s*historyStart\s*>>>/i);
      const eMatch = text.match(/<<<\|\s*catgodml\s*\|\s*historyEnd\s*>>>/i);
      const sPos = sMatch.index;
      const ePos = eMatch.index;
      const beforeH = text.slice(0, sPos).trim();
      const insideH = text.slice(sPos + sMatch[0].length, ePos).trim();
      const afterH = text.slice(ePos + eMatch[0].length).trim();

      if (beforeH) preHistChunks.push(beforeH);

      // 解析内联的 msgStart..msgEnd 与 wiStart:inline..wiEnd:inline
      const unesc = insideH
        .replace(/\\n/g, '\n')
        .replace(/\\r/g, '\r')
        .replace(/\\t/g, '\t')
        .replace(/\\"/g, '"')
        .replace(/\\\\/g, '\\');

      const inlineTokenRe =
        /<<<\|\s*catgodml\s*\|\s*(?:(msgStart:(user|model))([\s\S]*?)<<<\|\s*catgodml\s*\|\s*msgEnd:\2|(wiStart:inline)([\s\S]*?)<<<\|\s*catgodml\s*\|\s*wiEnd:inline)\s*>>>/gi;
      let tok;
      while ((tok = inlineTokenRe.exec(unesc)) !== null) {
        if (tok[1]) {
          const mRole = tok[2].toLowerCase();
          const mBody = tok[3].trim();
          if (mBody) {
            nativeChatMsgs.push({
              role: mRole,
              text: mBody,
              mediaParts: [],
              afterMsgIndex: nativeChatMsgs.length,
            });
          }
        } else if (tok[4]) {
          const wBody = tok[5].trim();
          if (wBody && !/^["'},\s-]+$/.test(wBody)) {
            inlineDepthWiList.push({
              text: wBody,
              msgCountBefore: nativeChatMsgs.length,
            });
          }
        }
      }

      if (afterH) postHistChunks.push(afterH);
      phase = 'after_hist';
      continue;
    }

    if (hasHistStart) {
      const [beforeH, afterH] = text.split(/<<<\|\s*catgodml\s*\|\s*historyStart\s*>>>/i);
      if (beforeH?.trim()) preHistChunks.push(beforeH.trim());
      phase = 'in_hist';
      const cleanAfter = (afterH ?? '').replace(/<<<\|\s*catgodml\s*\|[\s\S]*?>>>/gi, '').trim();
      if (cleanAfter) {
        inlineDepthWiList.push({
          text: cleanAfter,
          msgCountBefore: nativeChatMsgs.length,
        });
      }
      continue;
    }

    if (hasHistEnd) {
      const [beforeEnd, afterEnd] = text.split(/<<<\|\s*catgodml\s*\|\s*historyEnd\s*>>>/i);
      const cleanBefore = (beforeEnd ?? '').replace(/<<<\|\s*catgodml\s*\|[\s\S]*?>>>/gi, '').trim();
      if (cleanBefore) {
        inlineDepthWiList.push({
          text: cleanBefore,
          msgCountBefore: nativeChatMsgs.length,
        });
      }
      phase = 'after_hist';
      if (afterEnd?.trim()) postHistChunks.push(afterEnd.trim());
      continue;
    }

    const cleanedText = text.replace(/<<<\|\s*catgodml\s*\|[\s\S]*?>>>/gi, '').trim();
    if (cleanedText) {
      if (phase === 'after_hist') {
        postHistChunks.push(cleanedText);
      } else {
        preHistChunks.push(cleanedText);
      }
    }
  }

  // 将 preHistChunks 和 postHistChunks 通过内置平替后处理转换为伪 JSON 对话流
  const rawPreText = preHistChunks.join('\n');
  const rawPostText = postHistChunks.join('\n').replace(/<think>[\s\S]{0,800}$/i, '').trim();

  const worldPartText = convertPipeRolesToJson(rawPreText, true);
  const rulesPartText = convertPipeRolesToJson(rawPostText, false);

  const renderedMessagesCorpus = renderedMessagesPieces.join('\n\n');

  // 当轮实时注入池（严禁写入 catgod_oracle.ledger 或历史楼层 extra.catgod_oracle，彻底杜绝动态状态冻结与存档膨胀！）
  const baibaiHistoryArchives = [];
  const memoryBriefingChunks = [];
  const shujukuArchiveChunks = [];
  const shujukuLiveStateChunks = [];
  const liveDynamicConstWiChunks = [];
  const liveDynamicTriggeredWiChunks = [];
  const liveDynamicD0Chunks = [];

  // ── 4. 读取预设创作细则状态并执行存档级永久化增量 Diff ───────────────────
  async function scanPresetRules() {
    try {
      const settings = ctx?.chatCompletionSettings;
      if (!settings || !Array.isArray(settings.prompts)) return null;
      const orders = Array.isArray(settings.prompt_order) ? settings.prompt_order : [];
      const orderObj =
        orders.find(e => Number(e?.character_id) === 100001) ||
        orders.find(e => Number(e?.character_id) === 100000);
      if (!orderObj || !Array.isArray(orderObj.order)) return null;

      const pMap = new Map();
      for (const p of settings.prompts) {
        if (p && typeof p.identifier === 'string') pMap.set(p.identifier, p);
      }

      const menuRe =
        /<<<\|\s*catgodml\s*\|\s*(menu|radio)\s*[:：]\s*([^:：>|]+?)\s*[:：]\s*([^>|]+?)\s*>>>/i;
      const stripRe = /<<<\|[\s\S]*?>>>/g;
      const ruleMap = {};
      const activeIds = [];

      for (const item of orderObj.order) {
        const prompt = item && pMap.get(item.identifier);
        if (!prompt || prompt.marker) continue;
        const rawContent = String(prompt.content ?? '').replace(
          /\{\{\/\/[\s\S]*?\}\}/g,
          ''
        );
        if (item.enabled && /registerthinkingstep:/i.test(rawContent)) {
          rawContent.replace(catgodmlRegex, (_fm, rawDir) => {
            const dir = String(rawDir ?? '').trim();
            if (dir.toLowerCase().startsWith('registerthinkingstep:')) {
              parseAndRegisterThinkingStep(
                dir.slice('registerThinkingStep:'.length)
              );
            }
            return '';
          });
        }
        const m = menuRe.exec(rawContent) || menuRe.exec(String(prompt.name ?? ''));
        if (!m) continue;
        const cleanRuleRaw = rawContent.replace(stripRe, '').trim();

        // 若某条菜单规则本身包含动态模板语法（EJS / MVU 变量宏 / shujuku 动态语法），开启时实时编译放入动态池，绝不锁死账本
        if (hasDynamicTemplateSyntax(cleanRuleRaw)) {
          if (item.enabled) {
            const compiledRule = await compileDynamicEntryText(cleanRuleRaw);
            if (compiledRule && !isChatMode) {
              liveDynamicD0Chunks.push(`【${m[2].trim()}·${m[3].trim()}】\n${compiledRule}`);
            }
          }
          continue;
        }

        const info = {
          id: prompt.identifier,
          group: m[2].trim(),
          label: m[3].trim(),
          enabled: Boolean(item.enabled),
          content: cleanRuleRaw || m[3].trim(),
        };
        ruleMap[info.id] = info;
        if (info.enabled) activeIds.push(info.id);
      }
      return { ruleMap, activeIds };
    } catch {
      return null;
    }
  }

  const presetRulesInfo = await scanPresetRules();

  try {
    if (ctx?.eventSource && !hostWin.__catgodWiHookV2Bound) {
      const types = ctx.eventTypes || ctx.event_types || {};
      hostWin.__catgodWiHookBound = true;
      hostWin.__catgodWiHookV2Bound = true;
      if (types.GENERATION_STARTED) {
        ctx.eventSource.on(types.GENERATION_STARTED, (_type, _opts, dryRun) => {
          if (!dryRun) hostWin.__catgodLastActivatedWi = null;
        });
      }
      if (types.WORLD_INFO_ACTIVATED) {
        ctx.eventSource.on(types.WORLD_INFO_ACTIVATED, entries => {
          if (Array.isArray(entries)) {
            hostWin.__catgodLastActivatedWi = {
              updatedAt: Date.now(),
              chatId: String(ctx?.getCurrentChatId?.() ?? ctx?.chatId ?? ''),
              entries: entries.map(e => ({
                uid: e?.uid,
                world: e?.world,
                comment: e?.comment,
                content: e?.content,
                constant: Boolean(e?.constant),
                position: Number(e?.position),
                depth: Number(e?.depth),
                order: Number(e?.order ?? e?.insertion_order ?? 100),
                role: Number(e?.role),
              })),
            };
          }
        });
      }
    }
  } catch {
    /* ignore hook bind error */
  }

  const d0Entries = [];
  const beforeAfterConstantChunks = [];
  const depthConstantChunks = [];
  const dynamicWiChunks = [];

  // ── 4.1 显式读取 ctx.extensionPrompts（全面兼容柏宝书 ST-BaiBai-Book、自带总结、向量插件、/inject 等 IN_CHAT 扩展槽） ──
  const knownExtPromptTexts = new Set();
  if (ctx?.extensionPrompts && typeof ctx.extensionPrompts === 'object') {
    for (const [extKey, extObj] of Object.entries(ctx.extensionPrompts)) {
      if (!extObj || typeof extObj !== 'object') continue;
      const pos = Number(extObj.position);
      if (pos === -1) continue; // NONE (-1) 不注入提示词（如 acu_zero_layer_world_info_scan）
      if (
        extKey === 'PERSONA_DESCRIPTION' ||
        extKey === '2_floating_prompt' ||
        extKey === 'authors_note' ||
        extKey === '__STORY_STRING__' ||
        extKey === 'QUIET_PROMPT' ||
        extKey === 'acu_zero_layer_world_info_scan' ||
        extKey === 'baibai_book_memory' ||
        extKey.startsWith('customDepthWI') ||
        extKey.startsWith('customWIOutlet_')
      ) {
        continue;
      }
      const rawVal = String(extObj.value ?? '').trim();
      if (!rawVal) continue;
      knownExtPromptTexts.add(rawVal);

      const compiledVal = hasDynamicTemplateSyntax(rawVal)
        ? await compileDynamicEntryText(rawVal)
        : expandTavernHelperVarMacros(rawVal).trim();
      if (!compiledVal) continue;
      knownExtPromptTexts.add(compiledVal);

      // 1) 柏宝书专属四槽位精准分流（聊天模式下自动屏蔽剧场简报与时间标签强制要求，防止场外串戏）
      if (extKey === 'baibai_book_memory_history' || isBaiBaiHistoryChunk(compiledVal)) {
        if (!isChatMode) baibaiHistoryArchives.push(compiledVal);
        continue;
      }
      if (
        extKey === 'baibai_book_memory_state' ||
        extKey === 'baibai_book_vector_recall' ||
        isBaiBaiBriefingChunk(compiledVal)
      ) {
        if (!isChatMode) memoryBriefingChunks.push(compiledVal);
        continue;
      }
      if (extKey === 'baibai_book_time_tag' || isBaiBaiTimeTagChunk(compiledVal)) {
        if (!isChatMode) liveDynamicD0Chunks.push(compiledVal);
        continue;
      }

      // 2) 角色卡自带静态 Character Depth Prompt
      if (extKey === 'DEPTH_PROMPT' || extKey.startsWith('DEPTH_PROMPT_')) {
        const dVal = Number.isFinite(Number(extObj.depth)) ? Number(extObj.depth) : 4;
        if (hasDynamicTemplateSyntax(rawVal)) {
          if (!isChatMode) {
            (dVal === 0 ? liveDynamicD0Chunks : liveDynamicConstWiChunks).push(compiledVal);
          }
        } else if (dVal === 0) {
          d0Entries.push(compiledVal);
        } else {
          depthConstantChunks.push(compiledVal);
        }
        continue;
      }

      // 3) 其他第三方扩展提示词（自带总结 1_memory、向量召回 3_vectors/4_vectors_data_bank、脚本 /inject 等）：一律走实时动态池不锁死账本
      if (!isChatMode) {
        const dVal = Number.isFinite(Number(extObj.depth)) ? Number(extObj.depth) : 0;
        if (pos === 1 && dVal >= 4) {
          liveDynamicConstWiChunks.push(compiledVal);
        } else {
          liveDynamicD0Chunks.push(compiledVal);
        }
      }
    }
  }

  const activeWiRecord = hostWin?.__catgodLastActivatedWi;
  const hasActiveWiEvent = Boolean(
    activeWiRecord &&
      Array.isArray(activeWiRecord.entries) &&
      activeWiRecord.entries.length > 0
  );
  const knownDepthWiTexts = new Set();
  if (activeWiRecord && Array.isArray(activeWiRecord.entries)) {
    for (const entry of activeWiRecord.entries) {
      if (Number(entry?.position) === 4) {
        const t = String(entry?.content ?? '').trim();
        if (t) knownDepthWiTexts.add(t);
      }
    }
  }

  // 内联特殊块特征兜底分流器（防止第三方插件直接改写 messages 而未走 extensionPrompts 时漏网或污染静态账本）
  function routeInlineSpecialChunk(chunkText) {
    const t = String(chunkText ?? '').trim();
    if (!t) return true;
    if (knownExtPromptTexts.has(t)) return true;
    if (isBaiBaiHistoryChunk(t)) {
      if (!isChatMode && !baibaiHistoryArchives.includes(t)) {
        baibaiHistoryArchives.push(t);
      }
      return true;
    }
    if (isBaiBaiBriefingChunk(t)) {
      if (!isChatMode && !memoryBriefingChunks.includes(t)) {
        memoryBriefingChunks.push(t);
      }
      return true;
    }
    if (isBaiBaiTimeTagChunk(t)) {
      if (!isChatMode && !liveDynamicD0Chunks.includes(t)) {
        liveDynamicD0Chunks.push(t);
      }
      return true;
    }
    if (isShujukuFormattedChunk(t)) {
      // 若本次已有 WORLD_INFO_ACTIVATED，shujuku 世界书会在下方统一按 order 组装，此处直接去重跳过；若无事件则兜底分流
      if (!hasActiveWiEvent && !isChatMode) {
        if (/<(?:剧情大纲编码索引|大总结|已登场角色|重要角色索引)>|^#\s*(?:总体大纲|重要人物表)\b/m.test(t)) {
          if (!shujukuArchiveChunks.includes(t)) shujukuArchiveChunks.push(t);
        } else if (!shujukuLiveStateChunks.includes(t)) {
          shujukuLiveStateChunks.push(t);
        }
      }
      return true;
    }
    return false;
  }

  const rawPersonaText = expandTavernHelperVarMacros(
    String(ctx?.powerUserSettings?.persona_description ?? '')
  ).trim();
  const rawAuthorsNoteText = expandTavernHelperVarMacros(
    String(ctx?.chatMetadata?.note_prompt ?? '')
  ).trim();

  // 第一重净化：剔除明确匹配的 In-Chat Persona Description、Author's Note、已识别扩展提示槽与已知 @Depth 世界书
  const step1ChatMsgs = [];
  for (let idx = 0; idx < nativeChatMsgs.length; idx++) {
    const item = nativeChatMsgs[idx];
    const t = item.text;
    if (item.mediaParts.length === 0 && t) {
      if (rawPersonaText && t === rawPersonaText) {
        beforeAfterConstantChunks.unshift(`【玩家角色设定】\n${t}`);
        continue;
      }
      if (rawAuthorsNoteText && t === rawAuthorsNoteText) {
        d0Entries.push(`【作者注释】\n${t}`);
        continue;
      }
      if (routeInlineSpecialChunk(t)) {
        continue;
      }
      if (knownDepthWiTexts.has(t)) {
        if (!hasActiveWiEvent) {
          inlineDepthWiList.push({ text: t, msgCountBefore: step1ChatMsgs.length });
        }
        continue;
      }
    }
    step1ChatMsgs.push(item);
  }

  // 检测是否处于 shujuku 零层卡模式（Zero-Layer 会在 PROMPT_READY 中将单个 quiet 占位消息展开为多轮逻辑对话，此时 ctx.chat 不含这些逻辑楼层，不可用 DP 误剥！）
  const isZeroLayerActive = (() => {
    try {
      if (
        hostWin?.AutoCardUpdaterAPI?.zeroLayer &&
        liveVisibleMsgs.length <= 2 &&
        step1ChatMsgs.length > liveVisibleMsgs.length + 2
      ) {
        return true;
      }
    } catch {
      /* ignore */
    }
    return false;
  })();

  // 第二重净化（终极 DP 子序列对齐）：若 step1ChatMsgs 数量仍多于 ctx.chat 真实楼层数，通过最优子序列对齐揪出幽灵深度注入！
  const stripForCompare = s =>
    String(s ?? '')
      .replace(/<(?:think_nya|report_nya)~?>[\s\S]*?<\/(?:think_nya|report_nya)~?>(?:<!--<\/think>-->)?/gi, '')
      .replace(/<\/?[a-zA-Z][^>]*>/g, '')
      .replace(/\s+/g, '');

  let purifiedChatMsgs = step1ChatMsgs;
  if (
    !isZeroLayerActive &&
    liveVisibleMsgs.length > 0 &&
    step1ChatMsgs.length > liveVisibleMsgs.length
  ) {
    const targetVis = liveVisibleMsgs;
    const N = step1ChatMsgs.length;
    const M = targetVis.length;
    const normCand = step1ChatMsgs.map(c => stripForCompare(c.text));
    const normVis = targetVis.map(v => stripForCompare(v.m.mes));

    const scorePair = (i, j) => {
      const candRole = step1ChatMsgs[i].role;
      const visRole = targetVis[j].m.is_user ? 'user' : 'model';
      if (candRole !== visRole) return -1e6;
      const a = normCand[i];
      const b = normVis[j];
      if (!a && !b) return 50;
      if (a && b) {
        if (a === b) return 1000;
        const probeA = a.slice(0, Math.min(24, a.length));
        const probeB = b.slice(0, Math.min(24, b.length));
        const tailA = a.slice(-Math.min(24, a.length));
        const tailB = b.slice(-Math.min(24, b.length));
        if (
          (probeA.length >= 4 && b.includes(probeA)) ||
          (probeB.length >= 4 && a.includes(probeB)) ||
          (tailA.length >= 4 && b.includes(tailA)) ||
          (tailB.length >= 4 && a.includes(tailB))
        ) {
          return 500;
        }
        return -50;
      }
      return 5;
    };

    const NEG = -1e9;
    const dp = Array.from({ length: N + 1 }, () => new Array(M + 1).fill(NEG));
    const parent = Array.from({ length: N + 1 }, () => new Array(M + 1).fill(0));
    for (let j0 = 0; j0 <= M; j0++) {
      dp[0][j0] = -j0 * 2;
    }
    for (let i = 1; i <= N; i++) {
      for (let j = 0; j <= M; j++) {
        if (dp[i - 1][j] > dp[i][j]) {
          dp[i][j] = dp[i - 1][j];
          parent[i][j] = 1;
        }
        if (j >= 1 && dp[i - 1][j - 1] > NEG / 2) {
          const sc = dp[i - 1][j - 1] + scorePair(i - 1, j - 1);
          if (sc > dp[i][j]) {
            dp[i][j] = sc;
            parent[i][j] = 2;
          }
        }
      }
    }

    if (dp[N][M] > 0) {
      const keptIndices = new Set();
      let ci = N;
      let cj = M;
      while (ci > 0) {
        const act = parent[ci][cj];
        if (act === 2) {
          keptIndices.add(ci - 1);
          ci--;
          cj--;
        } else {
          ci--;
        }
      }
      const nextChatMsgs = [];
      for (let idx = 0; idx < N; idx++) {
        if (keptIndices.has(idx)) {
          nextChatMsgs.push(step1ChatMsgs[idx]);
        } else {
          const ghostText = step1ChatMsgs[idx].text;
          if (ghostText && !routeInlineSpecialChunk(ghostText)) {
            if (!knownDepthWiTexts.has(ghostText)) {
              if (hasDynamicTemplateSyntax(ghostText)) {
                liveDynamicConstWiChunks.push(await compileDynamicEntryText(ghostText));
              } else {
                beforeAfterConstantChunks.push(ghostText);
              }
            }
          }
        }
      }
      purifiedChatMsgs = nextChatMsgs;
    }
  }

  // 即使在 hasActiveWiEvent === true 时，inlineDepthWiList 中也可能包含非世界书的第三方 IN_CHAT 系统消息（兜底识别柏宝书等并分流！）
  if (hasActiveWiEvent && inlineDepthWiList.length > 0) {
    for (const item of inlineDepthWiList) {
      routeInlineSpecialChunk(item.text);
    }
  }

  // 辅助：清理 shujuku 空三明治包裹（例如 <记忆回溯> 或 <过往记忆> 仅有表头却无任何激活纪要行时直接剔除）
  function pruneEmptyShujukuWrappers(joinedText) {
    return String(joinedText ?? '')
      .replace(/<(记忆回溯|过往记忆)>[\s\S]*?\|[\s:-]+\|\s*<\/\1>/g, '')
      .replace(/\n{3,}/g, '\n\n')
      .trim();
  }

  // 辅助：若 shujuku 开启了 Agent 绿灯接管或 {[db...]}/{[sql...]}/<if> 动态模板，从已渲染消息池对齐求值结果
  const isAcuAgentTakeoverActive = (() => {
    try {
      return Boolean(hostWin?.AutoCardUpdaterAPI?.getAgentWorldbookState?.()?.active);
    } catch {
      return false;
    }
  })();

  const allRenderedWiBlocks = [
    ...extractedWiChunks,
    ...inlineDepthWiList.map(x => x.text),
  ];

  function resolveAcuDynamicTemplateFromRendered(rawText) {
    if (!hasShujukuDynamicTemplateSyntax(rawText)) return rawText;
    // 取首行非动态锚点（如 "# 表名" 或 "<最新数据与记录>"）在已渲染块中匹配由 handleChatCompletionReady_ACU 求值后的版本
    const firstStaticLine = String(rawText)
      .split('\n')
      .map(l => l.trim())
      .find(l => l.length >= 3 && !hasShujukuDynamicTemplateSyntax(l));
    if (firstStaticLine) {
      const hit = allRenderedWiBlocks.find(b => b.includes(firstStaticLine));
      if (hit) return hit;
    }
    return rawText;
  }

  if (hasActiveWiEvent) {
    // 按 (position asc, depth desc, order asc) 排序，确保 shujuku 的三明治包裹条目（WrapperStart -> Body -> WrapperEnd）顺序 100% 严丝合缝！
    const orderedEntries = [...activeWiRecord.entries].sort((a, b) => {
      const posA = Number.isFinite(Number(a?.position)) ? Number(a.position) : 0;
      const posB = Number.isFinite(Number(b?.position)) ? Number(b.position) : 0;
      if (posA !== posB) return posA - posB;
      const depA = Number.isFinite(Number(a?.depth)) ? Number(a.depth) : 4;
      const depB = Number.isFinite(Number(b?.depth)) ? Number(b.depth) : 4;
      if (depA !== depB) return depB - depA;
      const ordA = Number.isFinite(Number(a?.order)) ? Number(a.order) : 100;
      const ordB = Number.isFinite(Number(b?.order)) ? Number(b.order) : 100;
      return ordA - ordB;
    });

    const sortedDepthConstants = [];
    const shujukuArchiveParts = [];
    const shujukuLiveParts = [];

    for (const entry of orderedEntries) {
      let rawEntryText = String(entry?.content ?? '')
        .replace(/\{\{\/\/[\s\S]*?\}\}/g, '')
        .trim();
      if (!rawEntryText) continue;
      if (/<<<\|\s*catgodml\s*\|/i.test(rawEntryText)) {
        rawEntryText = rawEntryText
          .replace(catgodmlRegex, (fullMatch, rawDirective) => {
            const directive = rawDirective.trim();
            const lower = directive.toLowerCase();
            if (lower.startsWith('registerthinkingstep:')) {
              parseAndRegisterThinkingStep(
                directive.slice('registerThinkingStep:'.length)
              );
              return '';
            }
            if (lower.startsWith('registerpart:')) {
              const rest = directive.slice('registerPart:'.length);
              const colonIdx = rest.indexOf(':');
              if (colonIdx !== -1) {
                const partName = rest.slice(0, colonIdx).trim();
                const partDesc = rest.slice(colonIdx + 1).trim();
                if (partName) {
                  registeredParts.push({ name: partName, description: partDesc });
                }
              }
              return '';
            }
            return fullMatch;
          })
          .trim();
        if (!rawEntryText) continue;
      }
      const rawComment = String(entry?.comment ?? '').trim();

      // 若开启了 shujuku Agent 世界书绿灯接管，跳过已被 Agent 从最终请求消息中剥离的未放行绿灯条目
      if (
        isAcuAgentTakeoverActive &&
        !entry?.constant &&
        !isShujukuEntryComment(rawComment) &&
        !hasDynamicTemplateSyntax(rawEntryText)
      ) {
        const probe = rawEntryText.slice(0, Math.min(40, rawEntryText.length)).trim();
        if (probe.length >= 6 && !renderedMessagesCorpus.includes(probe)) {
          continue;
        }
      }

      // 1) 龙血玄黄·数据库（shujuku）专属世界书条目：绝不加机器 comment 前缀，保持三明治结构并按动静分流，严禁锁死进 ledger！
      if (isShujukuEntryComment(rawComment) || isShujukuFormattedChunk(rawEntryText)) {
        if (isChatMode) continue;
        let acuText = resolveAcuDynamicTemplateFromRendered(rawEntryText);
        if (hasDynamicTemplateSyntax(acuText)) {
          acuText = await compileDynamicEntryText(acuText);
        }
        if (!acuText) continue;
        if (isShujukuArchiveComment(rawComment)) {
          shujukuArchiveParts.push(acuText);
        } else {
          shujukuLiveParts.push(acuText);
        }
        continue;
      }

      const isDynamicEntry = hasDynamicTemplateSyntax(rawEntryText);
      let compiledText = rawEntryText;
      if (isDynamicEntry) {
        // 若条目包含写变量副作用（如 setvar/incvar），优先从已由 ST-Prompt-Template 首遍渲染的消息块中匹配成品，避免数值回显偏差
        let matchedPreRendered = null;
        if (hasEjsWriteSideEffect(rawEntryText)) {
          const staticAnchor = rawEntryText
            .replace(/<%[\s\S]*?%>/g, '\n')
            .split('\n')
            .map(l => l.trim())
            .find(l => l.length >= 4 && !l.includes('{{'));
          if (staticAnchor) {
            matchedPreRendered =
              allRenderedWiBlocks.find(
                b => !b.includes('<%') && b.includes(staticAnchor)
              ) || null;
          }
        }
        compiledText =
          matchedPreRendered !== null
            ? expandTavernHelperVarMacros(matchedPreRendered).trim()
            : await compileDynamicEntryText(rawEntryText);
      }
      if (!compiledText) continue; // EJS 求值为空代表条件未命中，直接过滤跳过！

      const labeled =
        rawComment && !compiledText.startsWith(rawComment) && !compiledText.startsWith(`【${rawComment}】`)
          ? `【${rawComment}】\n${compiledText}`
          : compiledText;
      const isAtDepth = Number(entry?.position) === 4;
      const depthVal = Number.isFinite(entry?.depth) ? Number(entry.depth) : 4;

      // 2) 含 EJS / MVU 动态变量语法的世界书条目：一律归入当轮实时注入池，严禁写入静态账本 ledger！
      if (isDynamicEntry) {
        if (!isChatMode) {
          if (isAtDepth && depthVal === 0) {
            liveDynamicD0Chunks.push(labeled);
          } else if (entry?.constant) {
            liveDynamicConstWiChunks.push(labeled);
          } else {
            liveDynamicTriggeredWiChunks.push(labeled);
          }
        }
        continue;
      }

      // 3) 纯静态世界书条目：走原有高缓存命中率账本基线 + 增量状态机
      if (isAtDepth && depthVal === 0) {
        d0Entries.push(labeled);
      } else if (isAtDepth && entry?.constant) {
        sortedDepthConstants.push({ depth: depthVal, text: labeled });
      } else if (entry?.constant) {
        beforeAfterConstantChunks.push(labeled);
      } else {
        dynamicWiChunks.push(labeled);
      }
    }

    if (shujukuArchiveParts.length > 0) {
      const cleanedArchive = pruneEmptyShujukuWrappers(shujukuArchiveParts.join('\n\n'));
      if (cleanedArchive) shujukuArchiveChunks.push(cleanedArchive);
    }
    if (shujukuLiveParts.length > 0) {
      const cleanedLive = pruneEmptyShujukuWrappers(shujukuLiveParts.join('\n\n'));
      if (cleanedLive) shujukuLiveStateChunks.push(cleanedLive);
    }

    sortedDepthConstants.sort((a, b) => b.depth - a.depth);
    for (const item of sortedDepthConstants) {
      depthConstantChunks.push(item.text);
    }
  } else {
    // 仅当无 WORLD_INFO_ACTIVATED 事件时，使用从消息提取的块，并同样执行插件分流与动态语法检测
    const totalChatMsgs = purifiedChatMsgs.length;
    for (const item of inlineDepthWiList) {
      if (routeInlineSpecialChunk(item.text)) continue;
      if (hasDynamicTemplateSyntax(item.text)) {
        const compiled = await compileDynamicEntryText(item.text);
        if (compiled && !isChatMode) {
          if (totalChatMsgs > 0 && item.msgCountBefore >= totalChatMsgs) {
            liveDynamicD0Chunks.push(compiled);
          } else {
            liveDynamicTriggeredWiChunks.push(compiled);
          }
        }
        continue;
      }
      if (totalChatMsgs > 0 && item.msgCountBefore >= totalChatMsgs) {
        d0Entries.push(item.text);
      } else {
        dynamicWiChunks.push(item.text);
      }
    }
    for (const chunk of extractedWiChunks) {
      if (routeInlineSpecialChunk(chunk)) continue;
      if (hasDynamicTemplateSyntax(chunk)) {
        const compiled = await compileDynamicEntryText(chunk);
        if (compiled && !isChatMode) liveDynamicConstWiChunks.push(compiled);
      } else {
        beforeAfterConstantChunks.push(chunk);
      }
    }
  }

  const isValidWiChunk = s =>
    typeof s === 'string' &&
    s.length > 0 &&
    !s.includes('<game>') &&
    !s.includes('</game>') &&
    !s.includes('<options>') &&
    !s.includes('</summary>');

  // 提取简短标题或摘要用于 deactivated 通知（绝不把几千字全文塞进 deactivated_info 浪费 Token！）
  const summarizeWiForDeactivation = chunk => {
    const s = String(chunk ?? '').trim();
    const titleMatch = s.match(/^【([^】]{1,60})】/);
    if (titleMatch) return `【${titleMatch[1]}】(已解除)`;
    const firstLine = s.split('\n')[0].trim().slice(0, 45);
    return `${firstLine}...(已解除)`;
  };

  const currentD0Set = [...new Set(d0Entries)].filter(isValidWiChunk);
  const currentBaseConstSet = [...new Set(beforeAfterConstantChunks)].filter(isValidWiChunk);
  const currentDepthConstSet = [...new Set(depthConstantChunks)].filter(isValidWiChunk);
  // 只有绿灯动态世界书进入 activated_info / deactivated_info 增量状态机，不把蓝灯常驻混入动态池
  const currentWiSet = [...new Set(dynamicWiChunks)].filter(isValidWiChunk);
  const currentPostHistBlocks = postHistChunks.map(s => s.trim()).filter(Boolean);

  // ── 4. 先构建历史聊天记录对（以确定当前是开局首轮还是后续轮次，并定位上一轮快照） ──
  const liveUserExtras = liveVisibleMsgs
    .filter(x => x.m.is_user)
    .map(x => x.m.extra?.catgod_oracle || null);
  // 提取原始 ctx.chat 中每条非首楼 AI 消息的“真实猫神身份提示”：
  // 即使酒馆/角色卡的 promptOnly 正则剥掉了 <think_nya> 或 <game>，只要原始存档含猫神标签或触发它的用户消息含 catgod_oracle 记录，就 100% 是猫神回复！
  const liveAiHints = [];
  for (let vIdx = 0; vIdx < liveVisibleMsgs.length; vIdx++) {
    const cur = liveVisibleMsgs[vIdx].m;
    if (cur.is_user) continue;
    const rawStr = String(cur.mes ?? '');
    const prevVis = vIdx > 0 ? liveVisibleMsgs[vIdx - 1].m : null;
    const triggeredUnderCatGod = Boolean(
      prevVis?.is_user && prevVis?.extra?.catgod_oracle
    );
    const rawHasCatGodSign =
      triggeredUnderCatGod ||
      /<(?:think_nya|report_nya|game|options|comment)\b/i.test(rawStr) ||
      /<details\b[^>]*>\s*<summary\b[^>]*>[^<]*小猫之神[^<]*<\/summary>/i.test(
        rawStr
      );
    liveAiHints.push({ rawMes: rawStr, isCatGodHint: rawHasCatGodSign });
  }
  const isHiddenOffset = liveVisibleMsgs.length > 0 && liveVisibleMsgs[0].index > 0;

  let openingArchiveBlock = '';
  let turn0FirstUserInput = '';
  let turn0FirstUserMedia = [];
  let latestActualUserInput = '';
  let latestActualUserMedia = [];
  const foreignArchivedBlocks = [];
  const historyPairs = [];

  if (purifiedChatMsgs.length > 0) {
    let userExtraCursor = 0;
    let aiHintCursor = 0;
    let startIdx = 0;
    if (purifiedChatMsgs[0].role === 'model') {
      openingArchiveBlock = formatInitialArchiveMessage(
        purifiedChatMsgs[0].text,
        isHiddenOffset
      );
      aiHintCursor++;
      if (purifiedChatMsgs.length >= 2 && purifiedChatMsgs[1].role === 'user') {
        turn0FirstUserInput = purifiedChatMsgs[1].text;
        turn0FirstUserMedia = purifiedChatMsgs[1].mediaParts || [];
        latestActualUserInput = turn0FirstUserInput;
        latestActualUserMedia = turn0FirstUserMedia;
        userExtraCursor++;
        startIdx = 2;
      } else {
        startIdx = 1;
      }
    } else if (purifiedChatMsgs[0].role === 'user') {
      turn0FirstUserInput = purifiedChatMsgs[0].text;
      turn0FirstUserMedia = purifiedChatMsgs[0].mediaParts || [];
      latestActualUserInput = turn0FirstUserInput;
      latestActualUserMedia = turn0FirstUserMedia;
      userExtraCursor++;
      startIdx = 1;
    }

    let pendingAiText = null;
    let pendingAiHint = false;
    let pendingAiRawSummarySource = '';
    for (let k = startIdx; k < purifiedChatMsgs.length; k++) {
      const item = purifiedChatMsgs[k];
      if (item.role === 'model') {
        const hintObj = liveAiHints[aiHintCursor++] || null;
        if (pendingAiText !== null) {
          // 连续多条 AI 消息（如群聊多角色连续发言）：合并拼接，绝不覆盖丢弃前一条！
          pendingAiText = `${pendingAiText}\n\n${item.text}`;
          pendingAiHint = pendingAiHint || Boolean(hintObj?.isCatGodHint);
          if (hintObj?.rawMes) {
            pendingAiRawSummarySource = `${pendingAiRawSummarySource}\n${hintObj.rawMes}`;
          }
        } else {
          pendingAiText = item.text;
          pendingAiHint = Boolean(hintObj?.isCatGodHint);
          pendingAiRawSummarySource = hintObj?.rawMes || '';
        }
      } else if (item.role === 'user') {
        const uExtra = liveUserExtras[userExtraCursor++] || null;
        const isLastMsg = k === purifiedChatMsgs.length - 1;
        latestActualUserInput = item.text;
        latestActualUserMedia = item.mediaParts || [];

        if (pendingAiText !== null) {
          let normAi = normalizeAssistantReply(
            pendingAiText,
            false,
            pendingAiHint
          );
          // 若角色卡 promptOnly 正则剥掉了 <summary>，可从原始 rawMes 补提 summary 供后续满 12 轮归档使用
          if (!normAi.summary && pendingAiRawSummarySource) {
            const rawNorm = normalizeAssistantReply(
              pendingAiRawSummarySource,
              false,
              pendingAiHint
            );
            if (rawNorm.summary) normAi.summary = rawNorm.summary;
          }

          if (!normAi.isCatGod && historyPairs.length === 0) {
            // 仅当真正处于切入猫神预设前的外人旧记录阶段：归入 Turn 0
            // 注意：若当前用户消息已经是最新一轮刚发的话（isLastMsg），绝不把玩家最新发言塞进旧档，而是留给末尾 syncPayload.user_input！
            const foreignSummary =
              normAi.summary ||
              normAi.game_content.replace(/<\/?game>/gi, '').trim();
            if (isLastMsg) {
              foreignArchivedBlocks.push(
                `---前情旧档记录---\n${foreignSummary}\n---`
              );
            } else {
              foreignArchivedBlocks.push(
                `---前情旧档记录---\n${foreignSummary}\n【玩家回应】：${item.text}\n---`
              );
            }
          } else {
            historyPairs.push({
              ai: normAi,
              userText: item.text,
              mediaParts: item.mediaParts || [],
              userExtra: uExtra,
              isLatestTurn: isLastMsg,
            });
          }
          pendingAiText = null;
          pendingAiHint = false;
          pendingAiRawSummarySource = '';
        } else {
          // 连续多条 User 消息（例如玩家连发两条才点生成，或漏网的附加发言）：合并进上一条用户发言，绝不静默吃掉！
          if (historyPairs.length > 0) {
            const prevPair = historyPairs.at(-1);
            if (item.text) {
              prevPair.userText = prevPair.userText
                ? `${prevPair.userText}\n\n${item.text}`
                : item.text;
            }
            if (item.mediaParts?.length) {
              prevPair.mediaParts = [...(prevPair.mediaParts || []), ...item.mediaParts];
            }
            if (uExtra) prevPair.userExtra = uExtra;
            if (isLastMsg) prevPair.isLatestTurn = true;
            latestActualUserInput = prevPair.userText;
          } else {
            if (item.text) {
              turn0FirstUserInput = turn0FirstUserInput
                ? `${turn0FirstUserInput}\n\n${item.text}`
                : item.text;
            }
            if (item.mediaParts?.length) {
              turn0FirstUserMedia = [...turn0FirstUserMedia, ...item.mediaParts];
            }
            latestActualUserInput = turn0FirstUserInput;
          }
        }
      }
    }
  } else if (liveVisibleMsgs.length > 0) {
    let startIdx = 0;
    if (!liveVisibleMsgs[0].m.is_user) {
      openingArchiveBlock = formatInitialArchiveMessage(
        String(liveVisibleMsgs[0].m.mes ?? '').trim(),
        isHiddenOffset
      );
      if (liveVisibleMsgs.length >= 2 && liveVisibleMsgs[1].m.is_user) {
        turn0FirstUserInput = String(liveVisibleMsgs[1].m.mes ?? '').trim();
        latestActualUserInput = turn0FirstUserInput;
        startIdx = 2;
      } else {
        startIdx = 1;
      }
    } else {
      turn0FirstUserInput = String(liveVisibleMsgs[0].m.mes ?? '').trim();
      latestActualUserInput = turn0FirstUserInput;
      startIdx = 1;
    }

    let pendingAi = null;
    for (let k = startIdx; k < liveVisibleMsgs.length; k++) {
      const { m, index } = liveVisibleMsgs[k];
      if (!m.is_user) {
        const prevVis = k > 0 ? liveVisibleMsgs[k - 1].m : null;
        const hint = Boolean(
          prevVis?.is_user && prevVis?.extra?.catgod_oracle
        );
        pendingAi = { mes: m.mes, index, hint };
      } else if (pendingAi) {
        const isLastMsg = index === lastUserChatIdx;
        const uText = String(m.mes ?? '').trim();
        latestActualUserInput = uText;
        const normAi = normalizeAssistantReply(
          pendingAi.mes,
          false,
          pendingAi.hint
        );
        if (!normAi.isCatGod && historyPairs.length === 0) {
          const foreignSummary =
            normAi.summary ||
            normAi.game_content.replace(/<\/?game>/gi, '').trim();
          if (isLastMsg) {
            foreignArchivedBlocks.push(
              `---前情旧档记录---\n${foreignSummary}\n---`
            );
          } else {
            foreignArchivedBlocks.push(
              `---前情旧档记录---\n${foreignSummary}\n【玩家回应】：${uText}\n---`
            );
          }
        } else {
          historyPairs.push({
            ai: normAi,
            userText: uText,
            mediaParts: [],
            userExtra: m.extra?.catgod_oracle || null,
            isLatestTurn: isLastMsg,
          });
        }
        pendingAi = null;
      }
    }
  }

  // 是否处于尚未产生后续完整问答对的首轮，或用户在控制台主动点击了【重建缓存】
  const isInitialRound = historyPairs.length === 0;
  const isForceRebuild = Boolean(oracleState.rebuildCache);
  const isBaselineRound = isInitialRound || isForceRebuild;

  if (isForceRebuild) {
    try {
      delete hostWin.__catgodPendingCacheRebuild;
      if (Array.isArray(liveChat)) {
        for (let i = 0; i < liveChat.length; i++) {
          if (i !== lastUserChatIdx && liveChat[i]?.extra?.catgod_oracle) {
            delete liveChat[i].extra.catgod_oracle;
          }
        }
      }
      for (const pair of historyPairs) {
        if (!pair.isLatestTurn) pair.userExtra = null;
      }
    } catch {
      /* ignore cleanup error */
    }
  }

  // 当前开启规则的 ID -> Content 字典（用于检测“未关开关但直接修改了条目文本”的情况）
  const currentActiveRuleContents = {};
  const currentRuleIds = presetRulesInfo ? presetRulesInfo.activeIds : [];
  if (presetRulesInfo) {
    for (const id of currentRuleIds) {
      const r = presetRulesInfo.ruleMap[id];
      if (r) currentActiveRuleContents[id] = r.content;
    }
  }

  // ── 5. 获取或刷新存档级账本 & 基于严格“上一轮快照”计算增量 ───────────────
  const getOrInitLedger = () => {
    hostWin.__catgodFallbackLedger = hostWin.__catgodFallbackLedger || {};
    const chatId = (() => {
      try {
        return String(ctx?.getCurrentChatId?.() ?? ctx?.chatId ?? 'default_chat');
      } catch {
        return 'default_chat';
      }
    })();

    let container = null;
    if (ctx?.chatMetadata && typeof ctx.chatMetadata === 'object') {
      ctx.chatMetadata.catgod_oracle = ctx.chatMetadata.catgod_oracle || {};
      container = ctx.chatMetadata.catgod_oracle;
    } else {
      hostWin.__catgodFallbackLedger[chatId] =
        hostWin.__catgodFallbackLedger[chatId] || {};
      container = hostWin.__catgodFallbackLedger[chatId];
    }

    // 关键修复：若处于首轮或手动触发【重建缓存】（isBaselineRound === true），直接用当前最新设定重建基线，绝不锁死旧版本！
    if (isBaselineRound || !container.ledger || container.ledger.schema !== 4) {
      let recoveredRuleIds = null;
      let recoveredRuleContents = null;
      let recoveredWi = null;
      let recoveredD0 = null;
      let recoveredPostBlocks = null;
      if (!isBaselineRound && Array.isArray(ctx?.chat)) {
        for (let i = ctx.chat.length - 1; i >= 0; i--) {
          const ex = ctx.chat[i]?.extra?.catgod_oracle;
          if (ex && ex.schema === 4 && Array.isArray(ex.activeRuleIds)) {
            recoveredRuleIds = ex.activeRuleIds;
            recoveredRuleContents = ex.activeRuleContents || null;
            recoveredWi = ex.activeWiChunks || [];
            recoveredD0 = ex.activeD0Chunks || [];
            recoveredPostBlocks = ex.activePostHistBlocks || null;
            break;
          }
        }
      }
      container.ledger = {
        schema: 4,
        createdAt: Date.now(),
        baseRuleIds: recoveredRuleIds || [...currentRuleIds],
        baseRuleContents: recoveredRuleContents || { ...currentActiveRuleContents },
        baseWiChunks: [...currentBaseConstSet],
        baseDynamicWiChunks: recoveredWi || [...currentWiSet],
        baseD0Chunks: recoveredD0 || [...currentD0Set],
        baseRulesText: rulesPartText || '',
        basePostHistBlocks: recoveredPostBlocks || [...currentPostHistBlocks],
        ruleCatalog: presetRulesInfo ? { ...presetRulesInfo.ruleMap } : {},
      };
    } else {
      if (!container.ledger.baseRulesText && rulesPartText) {
        container.ledger.baseRulesText = rulesPartText;
      }
      if (presetRulesInfo) {
        container.ledger.ruleCatalog = {
          ...(container.ledger.ruleCatalog || {}),
          ...presetRulesInfo.ruleMap,
        };
      }
    }
    return container.ledger;
  };

  const isCleanStaticWiChunk = s =>
    isValidWiChunk(s) && !isDirtyDynamicLedgerChunk(s);

  const ledger = getOrInitLedger();
  if (Array.isArray(ledger.baseWiChunks)) {
    ledger.baseWiChunks = ledger.baseWiChunks.filter(isCleanStaticWiChunk);
  }
  if (Array.isArray(ledger.baseDynamicWiChunks)) {
    ledger.baseDynamicWiChunks =
      ledger.baseDynamicWiChunks.filter(isCleanStaticWiChunk);
  }
  if (Array.isArray(ledger.baseD0Chunks)) {
    ledger.baseD0Chunks = ledger.baseD0Chunks.filter(isCleanStaticWiChunk);
  }

  // 关键修复：第 N 轮的对比基准严格取自“上一条用户消息（prevUserChatIdx）”或“Turn 0 初始基线（ledger.base*）”！
  // 绝不使用会被同轮第一次点击覆盖的临时变量，保证第 N 轮任意次 Swipe / 修改重roll 都能完整算出增量！
  const prevUserExtra =
    !isBaselineRound &&
    prevUserChatIdx >= 0 &&
    liveChat?.[prevUserChatIdx]?.extra?.catgod_oracle?.schema === 4
      ? liveChat[prevUserChatIdx].extra.catgod_oracle
      : null;

  const prevRuleIds = prevUserExtra?.activeRuleIds || ledger.baseRuleIds || [];
  const prevRuleContents =
    prevUserExtra?.activeRuleContents || ledger.baseRuleContents || {};
  const prevWiChunks = (
    prevUserExtra?.activeWiChunks ||
    ledger.baseDynamicWiChunks ||
    []
  ).filter(isCleanStaticWiChunk);
  const prevD0Chunks = (
    prevUserExtra?.activeD0Chunks ||
    ledger.baseD0Chunks ||
    []
  ).filter(isCleanStaticWiChunk);
  const prevPostHistBlocks =
    prevUserExtra?.activePostHistBlocks || ledger.basePostHistBlocks || [];

  const catalog = ledger.ruleCatalog || {};

  // 首轮或重建缓存轮（isBaselineRound）所有最新设定已直接写入 Turn 0 基线，无需重复发增量；
  // 后续轮次（!isBaselineRound）同时检测：1) 新打开的条目；2) 已打开但文本被直接修改的条目；3) 非 menu 的 Post-History 段落文字修改！
  const activatedRules = [];
  const deactivatedRules = [];

  if (!isBaselineRound) {
    for (const id of currentRuleIds) {
      const r = presetRulesInfo?.ruleMap?.[id] || catalog[id];
      if (!r) continue;
      if (!prevRuleIds.includes(id)) {
        activatedRules.push({ group: r.group, name: r.label, rule: r.content });
      } else if (
        prevRuleContents[id] !== undefined &&
        prevRuleContents[id] !== r.content
      ) {
        activatedRules.push({
          group: r.group,
          name: r.label,
          status: 'updated',
          rule: r.content,
        });
      }
    }

    for (const id of prevRuleIds) {
      if (!currentRuleIds.includes(id)) {
        const r = catalog[id];
        if (r) {
          deactivatedRules.push({
            group: r.group,
            name: r.label,
            status: 'deactivated',
          });
        }
      }
    }

    // 检测非 menu 的 Post-History 提示词段落是否有直接文字修改
    for (const blk of currentPostHistBlocks) {
      if (!prevPostHistBlocks.includes(blk)) {
        const isAlreadyInMenuRules = activatedRules.some(
          ar => ar.rule && blk.includes(ar.rule)
        );
        if (!isAlreadyInMenuRules) {
          activatedRules.push({
            group: '创作指令更新',
            name: '后置指令修改',
            status: 'updated',
            rule: blk,
          });
        }
      }
    }
  }

  const activatedInfo = isBaselineRound
    ? []
    : currentWiSet.filter(chunk => !prevWiChunks.includes(chunk));
  const deactivatedInfo = isBaselineRound
    ? []
    : prevWiChunks
        .filter(chunk => !currentWiSet.includes(chunk))
        .map(summarizeWiForDeactivation);
  const activatedD0 = isBaselineRound
    ? []
    : currentD0Set.filter(chunk => !prevD0Chunks.includes(chunk));
  const deactivatedD0 = isBaselineRound
    ? []
    : prevD0Chunks
        .filter(chunk => !currentD0Set.includes(chunk))
        .map(summarizeWiForDeactivation);

  if (liveChat && lastUserChatIdx >= 0 && liveChat[lastUserChatIdx]) {
    const targetMes = liveChat[lastUserChatIdx];
    targetMes.extra = targetMes.extra || {};
    targetMes.extra.catgod_oracle = {
      schema: 4,
      updatedAt: Date.now(),
      mode: oracleState.mode,
      activeRuleIds: [...currentRuleIds],
      activeRuleContents: { ...currentActiveRuleContents },
      activeWiChunks: [...currentWiSet],
      activeD0Chunks: [...currentD0Set],
      activePostHistBlocks: [...currentPostHistBlocks],
      delta: {
        activated_info: activatedInfo.filter(isValidWiChunk),
        deactivated_info: deactivatedInfo.filter(isValidWiChunk),
        d0_injections: activatedD0.filter(isValidWiChunk),
        deactivated_d0: deactivatedD0.filter(isValidWiChunk),
        activated_rules: activatedRules,
        deactivated_rules: deactivatedRules,
      },
    };
  }

  try {
    ctx?.saveMetadataDebounced?.();
  } catch {
    /* ignore save error */
  }

  // 最终安全锁：若预设末尾 setLastMessage:{{lastUserMessage}} 提供了权威最新发言，核对最后一轮 historyPairs 是否意外遗漏
  // 同时保护 shujuku 剧情推进（<本轮用户输入> / <plot>）：若历史消息已包裹完整剧情推进块且包含原始短句，绝不重复拼接或反向覆盖！
  if (historyPairs.length > 0 && explicitLastMessage) {
    const tailPair = historyPairs.at(-1);
    const normTail = stripForCompare(tailPair.userText);
    const normExplicit = stripForCompare(explicitLastMessage);
    if (normExplicit && !normTail.includes(normExplicit)) {
      if (normTail && normExplicit.includes(normTail)) {
        tailPair.userText = explicitLastMessage;
      } else {
        tailPair.userText = tailPair.userText
          ? `${tailPair.userText}\n\n${explicitLastMessage}`
          : explicitLastMessage;
      }
    }
  }

  let lastLine = '';
  const candidateHistoryTail =
    (historyPairs.length > 0 && historyPairs.at(-1)?.userText) ||
    latestActualUserInput ||
    (liveChat && lastUserChatIdx >= 0 && liveChat[lastUserChatIdx]?.mes
