  const fullContextPayload = `SoliUmbra World Context Registry.\n${combinedWorldAndRules}${catharsisTail}`;

  // ── 6. 动态组装 soliumbra_reply 与 context 工具定义 ──────────────────────
  const CIRCLED_NUMS = [
