  const activeExtraThinkSteps =
    enableDeepThink && !isChatMode
      ? [...registeredThinkingStepItems]
          .sort((a, b) => a.order - b.order || a.seq - b.seq)
          .map(x => x.text)
      : [];
  const numberedThinkStepsText =
    activeExtraThinkSteps.length > 0
      ? `分${activeExtraThinkSteps.length}个维度层层深入剖析：` +
        activeExtraThinkSteps
          .map((s, idx) => `${CIRCLED_NUMS[idx] || `(${idx + 1})`}${s}`)
