    hostWin.__catgodFinalSentPayload = finalPayload;
    hostWin.dispatchEvent(
      new hostWin.CustomEvent('catgod-oracle:final-request', {
        detail: finalPayload,
      })
    );
  } catch {
    /* ignore event dispatch error */
  }

  return request;
