    <script>
      (() => {
        'use strict';

        const rawData = document.getElementById('raw-data');
        const oracleTitle = document.getElementById('oracle-title');
        const oracleSubtitle = document.getElementById('oracleSubtitle');
        const toggle = document.getElementById('directSendToggle');
        const modeTitle = document.getElementById('modeTitle');
        const modeHint = document.getElementById('modeHint');

        const commentRegion = document.getElementById('commentRegion');
        const commentBody = document.getElementById('commentBody');
        const optionRegion = document.getElementById('optionRegion');
        const listRoot = document.getElementById('listRoot');
        const summaryRegion = document.getElementById('summaryRegion');
        const summaryDetails = document.getElementById('summaryDetails');
        const summaryBody = document.getElementById('summaryBody');

        const optionCount = document.getElementById('optionCount');
        const statusText = document.getElementById('statusText');
        const panel = document.querySelector('.oracle-panel');

        const optionModes = ['send', 'replace', 'append'];
        let optionMode = 'send';
        let selectedButton = null;
        let resizeFrame = 0;
        let hasExtraSections = false;

        function getSillyTavern() {
          try {
            return window.top?.SillyTavern || window.parent?.SillyTavern || null;
          } catch (error) {
            console.warn('[Cat Oracle] SillyTavern context is unavailable', error);
            return null;
          }
        }

        function setStatus(message, isError = false) {
          statusText.textContent = message;
          statusText.classList.toggle('is-error', isError);
        }

        function updateHeight() {
          resizeFrame = 0;
          if (window.parent && window.parent !== window) {
            window.parent.postMessage({ type: 'resizeIframe', height: document.body.scrollHeight }, '*');
          }
        }

        function scheduleHeightUpdate() {
          if (resizeFrame) cancelAnimationFrame(resizeFrame);
          resizeFrame = requestAnimationFrame(updateHeight);
        }

        function cleanTextFromHtml(html) {
          const template = document.createElement('template');
          template.innerHTML = html;
          template.content.querySelectorAll('script, style').forEach(el => el.remove());
          template.content.querySelectorAll('br').forEach(el => el.replaceWith('\n'));
          return (template.content.textContent || '').trim();
        }

        function looseOptionLinesFromHtml(html) {
          const template = document.createElement('template');
          template.innerHTML = html;
          template.content.querySelectorAll('script, style').forEach(element => element.remove());
          template.content.querySelectorAll('br').forEach(element => element.replaceWith('\n'));
          template.content.querySelectorAll('p, div, li').forEach(element => element.append('\n'));
          return (template.content.textContent || '')
            .split(/\r?\n/)
            .map(line => line
              .replace(/^\s*(?:[-*•]\s+|\d{1,3}[.)、]\s*)/, '')
              .trim())
            .filter(Boolean);
        }

        function extractTagBlocks(source, tagName) {
          const results = [];
          const regex = new RegExp(`<${tagName}\\b[^>]*>([\\s\\S]*?)<\\/${tagName}>`, 'gi');
          let match;
          while ((match = regex.exec(source)) !== null) {
            const cleaned = cleanTextFromHtml(match[1]);
            if (cleaned) results.push(cleaned);
          }
          return results;
        }

        function parseOptionsEntries(optionsRawList) {
          const entries = [];
          for (const optionsBody of optionsRawList) {
            const optionPattern = /<option\b[^>]*>([\s\S]*?)<\/option>/gi;
            let cursor = 0;
            let match;
            while ((match = optionPattern.exec(optionsBody)) !== null) {
              entries.push(...looseOptionLinesFromHtml(optionsBody.slice(cursor, match.index)));
              const text = cleanTextFromHtml(match[1]);
              if (text) entries.push(text);
              cursor = optionPattern.lastIndex;
            }
            entries.push(...looseOptionLinesFromHtml(optionsBody.slice(cursor)));
          }
          return entries;
        }

        function parseAndRender() {
          const source = String(rawData.innerHTML || '').trim();

          // 1. 提取 <comment>
          const comments = extractTagBlocks(source, 'comment');
          const hasComment = comments.length > 0;
          if (hasComment) {
            commentBody.textContent = comments.join('\n\n');
            commentRegion.hidden = false;
          } else {
            commentRegion.hidden = true;
          }

          // 2. 提取 <summary>
          const summaries = extractTagBlocks(source, 'summary');
          const hasSummary = summaries.length > 0;
          if (hasSummary) {
            summaryBody.textContent = summaries.join('\n\n');
            summaryRegion.hidden = false;
          } else {
            summaryRegion.hidden = true;
          }

          // 3. 提取 <options>
          const rawOptionsMatches = [];
          const optRegex = /<options\b[^>]*>([\s\S]*?)<\/options>/gi;
          let optMatch;
          while ((optMatch = optRegex.exec(source)) !== null) {
            rawOptionsMatches.push(optMatch[1]);
          }
          // 兼容直接传入裸选项内容的情况
          if (!rawOptionsMatches.length && !hasComment && !hasSummary && source) {
            rawOptionsMatches.push(source);
          }

          const entries = parseOptionsEntries(rawOptionsMatches);
          const hasOptions = entries.length > 0;
          hasExtraSections = hasComment || hasSummary;

          if (hasOptions) {
            optionRegion.hidden = false;
            toggle.hidden = false;
            oracleTitle.textContent = '请选择回应喵';
            oracleSubtitle.hidden = true;

            const fragment = document.createDocumentFragment();
            entries.forEach((text, index) => {
              const item = document.createElement('li');
              const button = document.createElement('button');
              const number = document.createElement('span');
              const copy = document.createElement('span');
              const paw = document.createElement('span');

              button.type = 'button';
              button.className = 'option-btn';
              button.style.setProperty('--delay', `${Math.min(index * 42, 252)}ms`);
              button.setAttribute('aria-label', `选择回应 ${index + 1}：${text}`);
              number.className = 'option-index';
              number.textContent = String(index + 1).padStart(2, '0');
              number.setAttribute('aria-hidden', 'true');
              copy.className = 'option-text';
              copy.textContent = text;
              paw.className = 'option-paw';
              paw.textContent = '♥';
              paw.setAttribute('aria-hidden', 'true');
              button.append(number, copy, paw);
              button.addEventListener('click', () => handleSelect(text, button));
              item.appendChild(button);
              fragment.appendChild(item);
            });
            listRoot.replaceChildren(fragment);
          } else {
            optionRegion.hidden = true;
            toggle.hidden = true;
            oracleTitle.textContent = hasComment && !hasSummary ? '小猫之神的悄悄话喵' : '神谕手札喵';
            oracleSubtitle.textContent = '本喵为你记下这一刻的轨迹啦';
            oracleSubtitle.hidden = false;
          }

          // 当只有 <summary>（没有 <options>）时，默认自动展开摘要
          if (hasSummary) {
            summaryDetails.open = !hasOptions;
          }

          // 4. 更新底部状态栏统计信息
          const parts = [];
          if (hasOptions) parts.push(`共 ${entries.length} 条回应`);
          if (hasComment) parts.push('猫神留言');
          if (hasSummary) parts.push('剧情摘要');
          optionCount.textContent = parts.length ? parts.join(' · ') : '神谕已送达';

          if (hasOptions) {
            setStatus('选一条就好喵');
          } else if (hasSummary) {
            setStatus('点击摘要标题可折叠/展开');
          } else {
            setStatus('喵呼呼~');
          }

          scheduleHeightUpdate();
        }

        function updateToggleUi() {
          const modeCopy = {
            send: ['直接发送', '点选后立即发出'],
            replace: ['仅填入', '覆盖输入框现有内容'],
            append: ['增量填入', '追加到输入框现有内容'],
          }[optionMode];
          toggle.dataset.mode = optionMode;
          toggle.setAttribute('aria-label', `当前模式：${modeCopy[0]}；点击切换`);
          modeTitle.textContent = modeCopy[0];
          modeHint.textContent = modeCopy[1];
        }

        function initToggle() {
          try {
            const st = getSillyTavern();
            const context = st?.getContext?.();
            const settings = context?.extensionSettings?.Astro;
            if (optionModes.includes(settings?.optionMode)) {
              optionMode = settings.optionMode;
            } else if (typeof settings?.directSend === 'boolean') {
              optionMode = settings.directSend ? 'send' : 'append';
            }
          } catch (error) {
            console.warn('[Cat Oracle] Failed to read direct-send setting', error);
          }

          updateToggleUi();
          toggle.addEventListener('click', () => {
            optionMode = optionModes[(optionModes.indexOf(optionMode) + 1) % optionModes.length];
            updateToggleUi();
            setStatus(`已切换为${modeTitle.textContent}`);

            try {
              const st = getSillyTavern();
              const context = st?.getContext?.();
              if (!context) return;
              context.extensionSettings ||= {};
              context.extensionSettings.Astro ||= {};
              context.extensionSettings.Astro.optionMode = optionMode;
              context.extensionSettings.Astro.directSend = optionMode === 'send';
              if (typeof st?.saveSettingsDebounced === 'function') st.saveSettingsDebounced();
              else context.saveSettingsDebounced?.();
            } catch (error) {
              console.error('[Cat Oracle] Failed to save direct-send setting', error);
              setStatus('模式已切换，但未能保存设置', true);
            }
            scheduleHeightUpdate();
          });
        }

        function removeOwnIframe() {
          try {
            const frames = window.parent?.document?.querySelectorAll('iframe') || [];
            for (const frame of frames) {
              if (frame.contentWindow === window) {
                frame.remove();
                break;
              }
            }
          } catch (error) {
            console.warn('[Cat Oracle] Failed to close option frame', error);
          }
        }

        function handleSelect(text, button) {
          try {
            const parentDocument = window.parent?.document;
            const textarea = parentDocument?.getElementById('send_textarea');
            if (!textarea) {
              setStatus('未找到酒馆输入框', true);
              return;
            }

            selectedButton?.classList.remove('is-selected');
            selectedButton = button;
            selectedButton.classList.add('is-selected');

            const currentValue = String(textarea.value || '');
            const separator = currentValue && !/\r?\n$/.test(currentValue) ? '\n' : '';
            const nextValue = optionMode === 'append' ? `${currentValue}${separator}${text}` : text;
            const parentWindow = window.parent;
            const textareaPrototype = parentWindow?.HTMLTextAreaElement?.prototype || HTMLTextAreaElement.prototype;
            const valueSetter = Object.getOwnPropertyDescriptor(textareaPrototype, 'value')?.set;
            if (valueSetter) valueSetter.call(textarea, nextValue);
            else textarea.value = nextValue;
            const ParentEvent = parentWindow?.Event || Event;
            textarea.dispatchEvent(new ParentEvent('input', { bubbles: true }));
            textarea.dispatchEvent(new ParentEvent('change', { bubbles: true }));
            textarea.focus();
            textarea.setSelectionRange?.(nextValue.length, nextValue.length);

            if (optionMode !== 'send') {
              setStatus(optionMode === 'append' ? '已追加到酒馆输入框' : '已填入酒馆输入框');
              return;
            }

            const st = getSillyTavern();
            const context = st?.getContext?.();
            if (typeof context?.generate === 'function') context.generate();
            else {
              const sendButton = parentDocument.getElementById('send_but');
              if (!sendButton) throw new Error('Send button is unavailable');
              sendButton.click();
            }

            // 如果卡片里还有 <comment> 或 <summary>，只收起选项区保留手札；若只有选项则移除整个 iframe
            if (hasExtraSections) {
              optionRegion.hidden = true;
              toggle.hidden = true;
              oracleTitle.textContent = '神谕手札喵';
              setStatus('已发送回应喵');
              scheduleHeightUpdate();
            } else {
              removeOwnIframe();
            }
          } catch (error) {
            console.error('[Cat Oracle] Failed to apply option', error);
            setStatus('未能应用这条回应，请检查控制台', true);
          }
        }

        window.addEventListener('DOMContentLoaded', () => {
          parseAndRender();
          initToggle();
          summaryDetails.addEventListener('toggle', scheduleHeightUpdate);
          scheduleHeightUpdate();
          window.addEventListener('resize', scheduleHeightUpdate);
          if ('ResizeObserver' in window) new ResizeObserver(scheduleHeightUpdate).observe(panel);
          document.fonts?.ready?.then(scheduleHeightUpdate);
        });
      })();
    </script>
