            const source = ctx.eventSource;
            const type = (ctx.eventTypes || ctx.event_types || {})[name];
            if (!source || typeof source.on !== 'function' || !type) return;
            const handler = (...args) => {
              try { fn(...args); } catch (error) { console.error(TAG, `${name} handler failed`, error); }
            };
